# Generated from tools/data/rulebooks/bridge.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  class Bridge
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:aim, GameRoomRules.translate("What the game is about"),
            GameRoomRules.translate("Bridge is a card game for four players in two partnerships. You and your partner work together against the other pair. Each deal has two parts: first an auction, in which the pairs compete to name a contract, and then the play, in which the pair that won the contract tries to take at least as many tricks as it promised."),
            GameRoomRules.translate("Points come from making contracts and from defeating the opponents' contracts. The pair with more points when the match ends wins.")),
          rule_section(:deal, GameRoomRules.translate("Partners and the deal"),
            GameRoomRules.translate("The players are named after the points of the compass. North and South are partners, and so are East and West; partners sit opposite each other. When the table chooses teams, the two members of each team become partners. Play always moves clockwise: North, East, South, West."),
            GameRoomRules.translate("All 52 cards are dealt, so everyone gets 13. Press H to hear your hand suit by suit, from the highest card down, followed by your high card points: an ace counts 4, a king 3, a queen 2 and a jack 1. These points are not scored; they help you judge the strength of your hand during the auction. A whole deck holds 40 such points, so 10 is an average hand and 12 or more is usually enough to start the bidding."),
            GameRoomRules.translate("In every suit the ace is the highest card, followed by the king, queen, jack and ten down to the two.")),
          rule_section(:auction, GameRoomRules.translate("The auction"),
            GameRoomRules.translate("The dealer makes the first call and the others follow clockwise. When it is your turn, the game field shows a list of the calls you may make. Choose one with the arrow keys and press Enter. You can also press B to open the same list."),
            GameRoomRules.translate("A bid names a number of tricks and a trump suit, or no trump. The number is added to six: a bid of 1 heart promises 7 of the 13 tricks with hearts as trumps, and 4 spades promises 10 tricks with spades as trumps. Each bid must be higher than the previous one. A higher number always wins, and at the same number the suits rank from the lowest: clubs, diamonds, hearts, spades and no trump. After 1 spade you may bid 1 no trump or anything at the level of 2, but not 1 heart."),
            GameRoomRules.translate("Instead of bidding you can make one of these calls:"),
            GameRoomRules.translate("- Pass: you do not want to bid now. Passing does not stop you from bidding later in the same auction."),
            GameRoomRules.translate("- Double: possible only right after an opponent's bid, or after an opponent's bid followed by passes. If that bid becomes the contract, it scores more for both sides: more for making it and more for defeating it."),
            GameRoomRules.translate("- Redouble: possible only after an opponent has doubled your side's bid. It raises the stakes once more."),
            GameRoomRules.translate("The auction ends when three players pass in a row after a bid. The last bid becomes the contract. If all four players pass at the start, nobody scores and the cards are dealt again by the next dealer."),
            GameRoomRules.translate("Press L to hear the whole auction, or Ctrl+L to go through it call by call.")),
          rule_section(:contract, GameRoomRules.translate("Contract, declarer and dummy"),
            GameRoomRules.translate("The pair that made the last bid must take the promised number of tricks; the other pair defends. The declarer is the player of the contracting pair who first bid the suit, or no trump, of the final contract. For example, if North opens 1 heart, South raises to 4 hearts and everyone passes, North is declarer even though South made the last bid."),
            GameRoomRules.translate("The player to the left of declarer leads the first card. Then declarer's partner becomes dummy: dummy's cards are laid face up for everyone, and declarer plays them as well as their own. Dummy takes no further part in the deal."),
            GameRoomRules.translate("Press K to hear the contract, who declares it and how many tricks declarer has taken so far.")),
          rule_section(:play, GameRoomRules.translate("Playing the cards"),
            GameRoomRules.translate("Each trick has four cards, one from each player in clockwise order. To play, go to a card in your hand with the arrow keys and press Enter. Z moves to the next card you are allowed to play and Shift+Z to the previous one; if you have only one playable card, Z plays it."),
            GameRoomRules.translate("You must follow the suit that was led if you can. If you have no card of that suit, you may play any card, including a trump, but you never have to trump. The highest trump in the trick wins it. If no trump was played, the highest card of the led suit wins. Cards of other suits cannot win the trick. The player who wins a trick leads to the next one."),
            GameRoomRules.translate("As declarer you also play dummy's cards. When it is dummy's turn, press Tab to move to the list of dummy's cards, or press Z, which goes straight to the cards dummy may play, and choose a card with Enter. Everyone can press D to hear dummy's hand."),
            GameRoomRules.translate("C reads the cards in the current trick and F the suit that was led. P repeats the previous trick, including who won it."),
            GameRoomRules.translate("After all 13 tricks the deal is scored, and the next deal starts with the next player clockwise as dealer.")),
          rule_section(:scoring, GameRoomRules.translate("Points for the contract"),
            GameRoomRules.translate("Only the tricks beyond the first six count. When declarer makes the contract, each contracted trick earns:"),
            GameRoomRules.translate("- 20 points in clubs or diamonds;"),
            GameRoomRules.translate("- 30 points in hearts or spades;"),
            GameRoomRules.translate("- 40 points for the first trick in no trump and 30 for each further trick."),
            GameRoomRules.translate("These contract points are doubled if the contract was doubled and multiplied by four if it was redoubled. A contract worth at least 100 of them is a game: 3 no trump, 4 hearts, 4 spades, 5 clubs and 5 diamonds are the lowest games. A smaller contract is a part score."),
            GameRoomRules.translate("Being vulnerable raises both the rewards and the penalties. Who is vulnerable is announced at the start of each deal; V repeats it together with the deal number, the dealer, the contract and the tricks."),
            GameRoomRules.translate("Extra tricks are called overtricks. Without a double each one is worth the same as a contracted trick of that suit. Doubled, each overtrick earns 100, or 200 when vulnerable; redoubled, 200 or 400. Making a doubled contract adds 50 points, and a redoubled one 100."),
            GameRoomRules.translate("A small slam (a contract of 6) earns a bonus of 500, or 750 when vulnerable. A grand slam (a contract of 7) earns 1000, or 1500 when vulnerable."),
            GameRoomRules.translate("If declarer falls short, the defenders score for each missing trick:"),
            GameRoomRules.translate("- not doubled: 50 per trick, or 100 when vulnerable;"),
            GameRoomRules.translate("- doubled and not vulnerable: 100 for the first trick, 200 each for the second and third, and 300 for each further trick;"),
            GameRoomRules.translate("- doubled and vulnerable: 200 for the first trick and 300 for each further trick;"),
            GameRoomRules.translate("- redoubled: twice the doubled amount."),
            GameRoomRules.translate("For example, 2 spades doubled, not vulnerable, made with an overtrick earns 120 for the contract, 50 for making a doubled contract and 100 for the overtrick. The same contract two tricks short gives the defenders 300.")),
          rule_section(:rubber, GameRoomRules.translate("Playing a rubber"),
            GameRoomRules.translate("By default the table plays rubber bridge. A rubber ends when one pair has won two games, and the pair with more points in total wins the match. This is usually, but not always, the pair that won the rubber; equal totals are a draw."),
            GameRoomRules.translate("Contract points are written below the line and everything else above it. A game is won when a pair's points below the line reach 100, either in one deal or from several part scores. After a game, both pairs start the next game from zero below the line; part scores the opponents had towards that game no longer help them."),
            GameRoomRules.translate("A pair that has won a game is vulnerable for the rest of the rubber. Winning the rubber earns 700 if the opponents won no game and 500 if they won one."),
            GameRoomRules.translate("Honours are also scored above the line, whoever holds them, even a defender. Four of the five top trumps (ace, king, queen, jack, ten) in one hand earn 100 and all five earn 150. In no trump, all four aces in one hand earn 150. The table settings can turn honours off."),
            GameRoomRules.translate("S reads the points below and above the line, the games won and the total for each pair, followed by the score towards the current game.")),
          rule_section(:duplicate, GameRoomRules.translate("Duplicate bridge"),
            GameRoomRules.translate("In the table settings you can choose duplicate bridge instead. The match then lasts a set number of deals, called boards: 4, 8, 12, 16 or 24, with 8 by default. The board number decides the dealer and vulnerability, in the cycle used at bridge clubs. Board 1 is dealt by North with neither side vulnerable, board 2 by East with North-South vulnerable, board 3 by South with East-West vulnerable and board 4 by West with both sides vulnerable."),
            GameRoomRules.translate("Each board is scored on its own. A game earns a bonus of 300, or 500 when vulnerable, and a part score earns 50. Everything else is scored as described above. There are no honours and no rubber."),
            GameRoomRules.translate("In a club, the same boards are played at many tables and pairs compare their results. Here there is only one table, so your result is compared with a reference score: an estimate of what these cards usually earn, based on the combined high card points of the stronger pair. A pair with 20 points each scores nothing on average. With 23 points the stronger pair is expected to score 110, with 26 points 400, or 600 vulnerable, and with 33 points a slam of 980, or 1430 vulnerable. The estimate ignores the shape of the hands, so a good fit or an unusual distribution can be worth much more."),
            GameRoomRules.translate("How the comparison is counted depends on the table's scoring choice:"),
            GameRoomRules.translate("- IMPs (the default): the difference from the reference score is converted into international match points. A difference of 10 or less is worth nothing, 20 to 40 is 1 IMP, 50 to 80 is 2 and 90 to 120 is 3. Larger swings earn more but more slowly: 420 is 9 IMPs and 4000 or more is the maximum of 24. The pair that did better than the reference gains the IMPs."),
            GameRoomRules.translate("- Matchpoints: on each board the pair that did better than the reference earns 2 points and the other pair 0; an equal result gives each pair 1. The final score is the percentage of the available points."),
            GameRoomRules.translate("A board passed out by all four players also counts: it scores zero and is compared with the reference, so passing with strong cards loses points. After the last board, the pair with more IMPs or matchpoints wins; an equal total is a draw. S reads the totals so far.")),
          rule_section(:bots, GameRoomRules.translate("Bidding with a computer partner"),
            GameRoomRules.translate("Computer players see only their own cards, dummy and the calls and cards everyone else can see. They bid a simple natural system, which helps you understand their calls:"),
            GameRoomRules.translate("- 1 no trump shows 15 to 17 points and a balanced hand; 2 no trump shows 20 or 21."),
            GameRoomRules.translate("- An opening bid of 1 heart or 1 spade promises at least five cards in that suit and usually 12 or more points. Without a five-card major, a bot opens 1 diamond or 1 club."),
            GameRoomRules.translate("- An opening bid of 2 diamonds, 2 hearts or 2 spades is weak: a six-card suit with 6 to 10 points."),
            GameRoomRules.translate("- A raise of your suit shows support. A raise to the level of 2 is weak, a raise to 3 invites game, and a jump to game is a strong hand."),
            GameRoomRules.translate("Bots never double. They play by simple rules too: the second player to a trick plays low unless it holds a sure winner, later players try to win the trick as cheaply as possible, and a defender leads partner's suit or a long suit.")),
          rule_section(:controls, GameRoomRules.translate("Keyboard shortcuts"),
            GameRoomRules.translate("Enter in the list of calls: make the selected call."),
            GameRoomRules.translate("B: choose a call when it is your turn, otherwise read the auction."),
            GameRoomRules.translate("L: read the auction."),
            GameRoomRules.translate("Ctrl+L: browse the auction."),
            GameRoomRules.translate("K: read the contract and declarer's tricks."),
            GameRoomRules.translate("Enter on a card: play it."),
            GameRoomRules.translate("Tab: move between your hand and dummy."),
            GameRoomRules.translate("Z: go to the next playable card in the hand that is to play; play it if it is the only one."),
            GameRoomRules.translate("Shift+Z: go to the previous playable card."),
            GameRoomRules.translate("H: read your hand."),
            GameRoomRules.translate("D: read dummy's hand."),
            GameRoomRules.translate("C: read the current trick."),
            GameRoomRules.translate("Ctrl+C: browse the current trick."),
            GameRoomRules.translate("F: read the led suit."),
            GameRoomRules.translate("P: read the previous trick."),
            GameRoomRules.translate("V: read the deal, vulnerability, contract and tricks."),
            GameRoomRules.translate("I: read your seat, partner and role in this deal."),
            GameRoomRules.translate("S: read the scores."),
            GameRoomRules.translate("T: read whose turn it is."),
            GameRoomRules.translate("Shift+C: sort your cards by suit."),
            GameRoomRules.translate("Shift+H: sort your cards by rank."),
            GameRoomRules.translate("Shift+M: restore the order in which you received your cards."))
        ]
      end

      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:aim, "O \u010Dem hra je",
              "Brid\u017E je karetn\u00ED hra pro \u010Dty\u0159i hr\u00E1\u010De ve dvou dvojic\u00EDch. Ty a tv\u016Fj partner hrajete spole\u010Dn\u011B proti druh\u00E9 dvojici. Ka\u017Ed\u00E9 rozd\u00E1n\u00ED m\u00E1 dv\u011B \u010D\u00E1sti: nejprve dra\u017Ebu, ve kter\u00E9 dvojice soupe\u0159\u00ED o z\u00E1vazek, a potom sehr\u00E1vku, ve kter\u00E9 se dvojice, kter\u00E1 z\u00E1vazek vydra\u017Eila, sna\u017E\u00ED uhr\u00E1t alespo\u0148 tolik zdvih\u016F, kolik sl\u00EDbila.",
              "Body se z\u00EDsk\u00E1vaj\u00ED za spln\u011Bn\u00E9 z\u00E1vazky a za pora\u017Een\u00ED z\u00E1vazk\u016F soupe\u0159\u016F. Vyhr\u00E1v\u00E1 dvojice, kter\u00E1 m\u00E1 na konci z\u00E1pasu v\u00EDce bod\u016F."),
            rule_section(:deal, "Dvojice a rozd\u00E1n\u00ED",
              "Hr\u00E1\u010Di se jmenuj\u00ED podle sv\u011Btov\u00FDch stran. Sever hraje s Jihem a V\u00FDchod se Z\u00E1padem; partne\u0159i sed\u00ED proti sob\u011B. Pokud si st\u016Fl zvol\u00ED t\u00FDmy, dva \u010Dlenov\u00E9 jednoho t\u00FDmu jsou partne\u0159i. Hraje se v\u017Edy po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek: Sever, V\u00FDchod, Jih, Z\u00E1pad.",
              "Rozd\u00E1 se v\u0161ech 52 karet, tak\u017Ee ka\u017Ed\u00FD dostane 13. Kl\u00E1vesou H si poslechne\u0161 sv\u016Fj list barvu po barv\u011B od nejvy\u0161\u0161\u00ED karty a nakonec po\u010Det figurov\u00FDch bod\u016F: eso m\u00E1 4 body, kr\u00E1l 3, d\u00E1ma 2 a kluk 1. Tyto body se nezapisuj\u00ED, pom\u00E1haj\u00ED ale odhadnout s\u00EDlu listu v dra\u017Eb\u011B. Cel\u00FD bal\u00ED\u010Dek jich m\u00E1 40, tak\u017Ee pr\u016Fm\u011Brn\u00FD list m\u00E1 10 bod\u016F a 12 nebo v\u00EDce obvykle sta\u010D\u00ED k zah\u00E1jen\u00ED dra\u017Eby.",
              "V ka\u017Ed\u00E9 barv\u011B je nejvy\u0161\u0161\u00ED eso, potom kr\u00E1l, d\u00E1ma, kluk, des\u00EDtka a dal\u0161\u00ED karty a\u017E po dvojku."),
            rule_section(:auction, "Dra\u017Eba",
              "Dra\u017Ebu zahajuje rozd\u00E1vaj\u00EDc\u00ED a ostatn\u00ED pokra\u010Duj\u00ED po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek. Kdy\u017E jsi na \u0159ad\u011B, v hern\u00EDm poli se objev\u00ED seznam hl\u00E1\u0161ek, kter\u00E9 m\u016F\u017Ee\u0161 pou\u017E\u00EDt. Vyber hl\u00E1\u0161ku \u0161ipkami a stiskni Enter. Stejn\u00FD seznam otev\u0159e i kl\u00E1vesa B.",
              "Licitace ur\u010Duje po\u010Det zdvih\u016F a trumfovou barvu, nebo hru bez trumf\u016F. K uveden\u00E9mu \u010D\u00EDslu se p\u0159i\u010D\u00EDt\u00E1 \u0161est: 1 srdce slibuje 7 ze 13 zdvih\u016F se srdci jako trumfy a 4 piky slibuj\u00ED 10 zdvih\u016F s piky jako trumfy. Ka\u017Ed\u00E1 licitace mus\u00ED b\u00FDt vy\u0161\u0161\u00ED ne\u017E p\u0159edchoz\u00ED. Vy\u0161\u0161\u00ED \u010D\u00EDslo v\u017Edy p\u0159eb\u00EDj\u00ED ni\u017E\u0161\u00ED a p\u0159i stejn\u00E9m \u010D\u00EDsle jsou barvy se\u0159azeny od nejni\u017E\u0161\u00ED: k\u0159\u00ED\u017Ee, k\u00E1ra, srdce, piky a bez trumf\u016F. Po 1 piku m\u016F\u017Ee\u0161 licitovat 1 bez trumf\u016F nebo cokoli na \u00FArovni 2, ale ne 1 srdce.",
              "M\u00EDsto licitace m\u016F\u017Ee\u0161 pou\u017E\u00EDt jednu z t\u011Bchto hl\u00E1\u0161ek:",
              "- Pas: te\u010F nechce\u0161 licitovat. Pas ti nebr\u00E1n\u00ED ozvat se pozd\u011Bji ve stejn\u00E9 dra\u017Eb\u011B.",
              "- Kontra: je mo\u017En\u00E1 jen po licitaci soupe\u0159e, i kdy\u017E po n\u00ED n\u00E1sledovaly pasy. Pokud se tato licitace stane z\u00E1vazkem, ob\u011B strany z\u00EDskaj\u00ED v\u00EDc: hlavn\u00ED hr\u00E1\u010D za spln\u011Bn\u00ED a obr\u00E1nci za p\u00E1d.",
              "- Rekontra: je mo\u017En\u00E1 jen tehdy, kdy\u017E soupe\u0159 kontroval licitaci tv\u00E9 dvojice. Je\u0161t\u011B jednou zvy\u0161uje s\u00E1zky.",
              "Dra\u017Eba kon\u010D\u00ED, kdy\u017E po licitaci t\u0159i hr\u00E1\u010Di za sebou pasuj\u00ED. Posledn\u00ED licitace se st\u00E1v\u00E1 z\u00E1vazkem. Pokud hned na za\u010D\u00E1tku pasuj\u00ED v\u0161ichni \u010Dty\u0159i, nikdo nez\u00EDsk\u00E1 body a karty znovu rozd\u00E1 dal\u0161\u00ED hr\u00E1\u010D.",
              "Kl\u00E1vesa L p\u0159e\u010Dte celou dra\u017Ebu a Ctrl+L umo\u017En\u00ED proch\u00E1zet ji hl\u00E1\u0161ku po hl\u00E1\u0161ce."),
            rule_section(:contract, "Z\u00E1vazek, hlavn\u00ED hr\u00E1\u010D a st\u016Fl",
              "Dvojice, kter\u00E1 dala posledn\u00ED licitaci, mus\u00ED uhr\u00E1t sl\u00EDben\u00FD po\u010Det zdvih\u016F a druh\u00E1 dvojice se br\u00E1n\u00ED. Hlavn\u00EDm hr\u00E1\u010Dem se stane ten hr\u00E1\u010D t\u00E9to dvojice, kter\u00FD jako prvn\u00ED jmenoval barvu z\u00E1vazku, nebo bez trumf\u016F. Kdy\u017E nap\u0159\u00EDklad Sever zah\u00E1j\u00ED 1 srdce, Jih zv\u00FD\u0161\u00ED na 4 srdce a v\u0161ichni pasuj\u00ED, hlavn\u00EDm hr\u00E1\u010Dem je Sever, p\u0159esto\u017Ee posledn\u00ED licitaci dal Jih.",
              "Prvn\u00ED kartu, v\u00FDnos, zahraje hr\u00E1\u010D vlevo od hlavn\u00EDho hr\u00E1\u010De. Potom se partner hlavn\u00EDho hr\u00E1\u010De stane stolem: jeho karty le\u017E\u00ED otev\u0159en\u011B pro v\u0161echny a hlavn\u00ED hr\u00E1\u010D jimi hraje stejn\u011B jako sv\u00FDmi. St\u016Fl se d\u00E1l rozd\u00E1n\u00ED ne\u00FA\u010Dastn\u00ED.",
              "Kl\u00E1vesa K \u0159ekne z\u00E1vazek, hlavn\u00EDho hr\u00E1\u010De a kolik zdvih\u016F u\u017E hlavn\u00ED hr\u00E1\u010D uhr\u00E1l."),
            rule_section(:play, "Sehr\u00E1vka",
              "Ka\u017Ed\u00FD zdvih tvo\u0159\u00ED \u010Dty\u0159i karty, jedna od ka\u017Ed\u00E9ho hr\u00E1\u010De po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek. Chce\u0161-li zahr\u00E1t, p\u0159ejdi \u0161ipkami na kartu ve sv\u00E9m listu a stiskni Enter. Kl\u00E1vesa Z t\u011B p\u0159esune na dal\u0161\u00ED kartu, kterou sm\u00ED\u0161 zahr\u00E1t, a Shift+Z na p\u0159edchoz\u00ED; pokud m\u016F\u017Ee\u0161 zahr\u00E1t jen jednu kartu, Z ji rovnou zahraje.",
              "M\u00E1\u0161-li kartu vynesen\u00E9 barvy, mus\u00ED\u0161 ji p\u0159iznat. Kdy\u017E ji nem\u00E1\u0161, sm\u00ED\u0161 zahr\u00E1t jakoukoli kartu v\u010Detn\u011B trumfu, ale p\u0159eb\u00EDjet nikdy nemus\u00ED\u0161. Zdvih bere nejvy\u0161\u0161\u00ED trumf, a pokud nikdo trumf nezahr\u00E1l, nejvy\u0161\u0161\u00ED karta vynesen\u00E9 barvy. Karty ostatn\u00EDch barev zdvih vz\u00EDt nemohou. Kdo zdvih vzal, vyn\u00E1\u0161\u00ED do dal\u0161\u00EDho.",
              "Jako hlavn\u00ED hr\u00E1\u010D hraje\u0161 i kartami stolu. Kdy\u017E je na \u0159ad\u011B st\u016Fl, stiskni Tab a p\u0159ejdi na seznam jeho karet, nebo stiskni Z, kter\u00E9 t\u011B rovnou p\u0159esune na karty, je\u017E st\u016Fl sm\u00ED zahr\u00E1t, a kartu vyber Enterem. List stolu si kl\u00E1vesou D kdykoli p\u0159e\u010Dte kdokoli.",
              "Kl\u00E1vesa C p\u0159e\u010Dte karty v aktu\u00E1ln\u00EDm zdvihu a F vynesenou barvu. P zopakuje p\u0159edchoz\u00ED zdvih i s t\u00EDm, kdo ho vzal.",
              "Po v\u0161ech 13 zdviz\u00EDch se rozd\u00E1n\u00ED spo\u010D\u00EDt\u00E1 a dal\u0161\u00ED rozd\u00E1v\u00E1 n\u00E1sleduj\u00EDc\u00ED hr\u00E1\u010D po sm\u011Bru hodinov\u00FDch ru\u010Di\u010Dek."),
            rule_section(:scoring, "Body za z\u00E1vazek",
              "Po\u010D\u00EDtaj\u00ED se jen zdvihy nad prvn\u00EDch \u0161est. Kdy\u017E hlavn\u00ED hr\u00E1\u010D z\u00E1vazek spln\u00ED, ka\u017Ed\u00FD zdvih z\u00E1vazku m\u00E1 hodnotu:",
              "- 20 bod\u016F v k\u0159\u00ED\u017E\u00EDch nebo k\u00E1rech;",
              "- 30 bod\u016F v srdc\u00EDch nebo pic\u00EDch;",
              "- 40 bod\u016F za prvn\u00ED zdvih bez trumf\u016F a 30 za ka\u017Ed\u00FD dal\u0161\u00ED.",
              "Tyto body za z\u00E1vazek se po kont\u0159e zdvojn\u00E1sob\u00ED a po rekont\u0159e ze\u010Dty\u0159n\u00E1sob\u00ED. Z\u00E1vazek za alespo\u0148 100 takov\u00FDch bod\u016F je hra: nejni\u017E\u0161\u00ED hry jsou 3 bez trumf\u016F, 4 srdce, 4 piky, 5 k\u0159\u00ED\u017E\u016F a 5 k\u00E1r. Men\u0161\u00ED z\u00E1vazek je \u010D\u00E1ste\u010Dn\u00FD z\u00E1vazek.",
              "Hra v man\u0161i zvy\u0161uje odm\u011Bny i tresty. Na za\u010D\u00E1tku ka\u017Ed\u00E9ho rozd\u00E1n\u00ED zazn\u00ED, kdo je v man\u0161i a kdo p\u0159ed man\u0161\u00ED; kl\u00E1vesa V to zopakuje spolu s \u010D\u00EDslem rozd\u00E1n\u00ED, rozd\u00E1vaj\u00EDc\u00EDm, z\u00E1vazkem a zdvihy.",
              "Zdvihy nav\u00EDc jsou p\u0159ezdvihy. Bez kontry m\u00E1 ka\u017Ed\u00FD hodnotu zdvihu z\u00E1vazku v dan\u00E9 barv\u011B. Po kont\u0159e p\u0159in\u00E1\u0161\u00ED ka\u017Ed\u00FD p\u0159ezdvih 100 bod\u016F, v man\u0161i 200; po rekont\u0159e 200 nebo 400. Za spln\u011Bn\u00ED kontrovan\u00E9ho z\u00E1vazku se p\u0159id\u00E1v\u00E1 50 bod\u016F, za spln\u011Bn\u00ED rekontrovan\u00E9ho 100.",
              "Mal\u00FD slem, tedy z\u00E1vazek na \u00FArovni 6, p\u0159in\u00E1\u0161\u00ED pr\u00E9mii 500, v man\u0161i 750. Velk\u00FD slem, z\u00E1vazek na \u00FArovni 7, p\u0159in\u00E1\u0161\u00ED 1000, v man\u0161i 1500.",
              "Pokud hlavn\u00ED hr\u00E1\u010D uhraje m\u00E1lo zdvih\u016F, obr\u00E1nci z\u00EDskaj\u00ED body za ka\u017Ed\u00FD chyb\u011Bj\u00EDc\u00ED zdvih, tedy p\u00E1d:",
              "- bez kontry: 50 za zdvih, v man\u0161i 100;",
              "- s kontrou p\u0159ed man\u0161\u00ED: 100 za prvn\u00ED p\u00E1d, po 200 za druh\u00FD a t\u0159et\u00ED a po 300 za ka\u017Ed\u00FD dal\u0161\u00ED;",
              "- s kontrou v man\u0161i: 200 za prvn\u00ED p\u00E1d a po 300 za ka\u017Ed\u00FD dal\u0161\u00ED;",
              "- s rekontrou: dvojn\u00E1sobek hodnoty s kontrou.",
              "Nap\u0159\u00EDklad 2 piky s kontrou p\u0159ed man\u0161\u00ED spln\u011Bn\u00E9 s jedn\u00EDm p\u0159ezdvihem p\u0159inesou 120 za z\u00E1vazek, 50 za spln\u011Bn\u00ED kontrovan\u00E9ho z\u00E1vazku a 100 za p\u0159ezdvih. Stejn\u00FD z\u00E1vazek se dv\u011Bma p\u00E1dy d\u00E1 obr\u00E1nc\u016Fm 300."),
            rule_section(:rubber, "Hra na robr",
              "Ve v\u00FDchoz\u00EDm nastaven\u00ED se u stolu hraje na robr. Robr kon\u010D\u00ED, kdy\u017E jedna dvojice vyhraje dv\u011B hry, a z\u00E1pas vyhr\u00E1v\u00E1 dvojice s vy\u0161\u0161\u00EDm celkov\u00FDm po\u010Dtem bod\u016F. Obvykle je to dvojice, kter\u00E1 vyhr\u00E1la robr, ale ne v\u017Edy; p\u0159i stejn\u00E9m sou\u010Dtu je rem\u00EDza.",
              "Body za z\u00E1vazek se zapisuj\u00ED pod \u010D\u00E1ru a v\u0161echny ostatn\u00ED nad \u010D\u00E1ru. Hru vyhraje dvojice, jej\u00ED\u017E body pod \u010Darou dos\u00E1hnou 100, a\u0165 u\u017E v jednom rozd\u00E1n\u00ED, nebo z n\u011Bkolika \u010D\u00E1ste\u010Dn\u00FDch z\u00E1vazk\u016F. Po vyhran\u00E9 h\u0159e za\u010D\u00EDnaj\u00ED ob\u011B dvojice dal\u0161\u00ED hru od nuly pod \u010Darou; \u010D\u00E1ste\u010Dn\u00E9 z\u00E1vazky, kter\u00E9 soupe\u0159i m\u011Bli k p\u0159edchoz\u00ED h\u0159e, jim u\u017E nepomohou.",
              "Dvojice, kter\u00E1 vyhr\u00E1la hru, je do konce robru v man\u0161i. Za vyhran\u00FD robr se z\u00EDsk\u00E1 700 bod\u016F, pokud soupe\u0159i nevyhr\u00E1li \u017E\u00E1dnou hru, a 500, pokud vyhr\u00E1li jednu.",
              "Nad \u010D\u00E1ru se zapisuj\u00ED i hon\u00E9ry, a\u0165 je dr\u017E\u00ED kdokoli, i obr\u00E1nce. \u010Cty\u0159i z p\u011Bti nejvy\u0161\u0161\u00EDch trumf\u016F (eso, kr\u00E1l, d\u00E1ma, kluk, des\u00EDtka) v jednom listu p\u0159in\u00E1\u0161ej\u00ED 100 a v\u0161ech p\u011Bt 150. Bez trumf\u016F p\u0159in\u00E1\u0161ej\u00ED v\u0161echna \u010Dty\u0159i esa v jednom listu 150. Po\u010D\u00EDt\u00E1n\u00ED hon\u00E9r\u016F lze vypnout v nastaven\u00ED stolu.",
              "Kl\u00E1vesa S p\u0159e\u010Dte body pod \u010Darou a nad \u010Darou, vyhran\u00E9 hry a sou\u010Det ka\u017Ed\u00E9 dvojice a potom stav rozehran\u00E9 hry."),
            rule_section(:duplicate, "Sportovn\u00ED brid\u017E",
              "V nastaven\u00ED stolu m\u016F\u017Ee\u0161 m\u00EDsto toho zvolit sportovn\u00ED brid\u017E. Z\u00E1pas pak trv\u00E1 stanoven\u00FD po\u010Det rozd\u00E1n\u00ED: 4, 8, 12, 16 nebo 24, v\u00FDchoz\u00ED je 8. \u010C\u00EDslo rozd\u00E1n\u00ED ur\u010Duje rozd\u00E1vaj\u00EDc\u00EDho a man\u0161e ve stejn\u00E9m cyklu jako v brid\u017Eov\u00FDch klubech. Rozd\u00E1n\u00ED 1 rozd\u00E1v\u00E1 Sever a ob\u011B dvojice jsou p\u0159ed man\u0161\u00ED, rozd\u00E1n\u00ED 2 V\u00FDchod s Severem a Jihem v man\u0161i, rozd\u00E1n\u00ED 3 Jih s V\u00FDchodem a Z\u00E1padem v man\u0161i a rozd\u00E1n\u00ED 4 Z\u00E1pad s ob\u011Bma dvojicemi v man\u0161i.",
              "Ka\u017Ed\u00E9 rozd\u00E1n\u00ED se po\u010D\u00EDt\u00E1 zvl\u00E1\u0161\u0165. Hra p\u0159in\u00E1\u0161\u00ED pr\u00E9mii 300, v man\u0161i 500, a \u010D\u00E1ste\u010Dn\u00FD z\u00E1vazek 50. V\u0161e ostatn\u00ED se po\u010D\u00EDt\u00E1, jak je pops\u00E1no v\u00FD\u0161e. Nejsou zde hon\u00E9ry ani robr.",
              "V klubu se stejn\u00E1 rozd\u00E1n\u00ED hraj\u00ED u mnoha stol\u016F a dvojice porovn\u00E1vaj\u00ED sv\u00E9 v\u00FDsledky. Tady je jen jeden st\u016Fl, tak\u017Ee tv\u016Fj v\u00FDsledek se porovn\u00E1v\u00E1 s referen\u010Dn\u00EDm v\u00FDsledkem: odhadem, kolik takov\u00E9 karty obvykle p\u0159inesou, podle sou\u010Dtu figurov\u00FDch bod\u016F siln\u011Bj\u0161\u00ED dvojice. Kdy\u017E maj\u00ED ob\u011B dvojice po 20 bodech, referen\u010Dn\u00ED v\u00FDsledek je nula. S 23 body by siln\u011Bj\u0161\u00ED dvojice m\u011Bla z\u00EDskat 110, s 26 body 400, v man\u0161i 600, a s 33 body mal\u00FD slem za 980, v man\u0161i 1430. Odhad nebere ohled na rozlo\u017Een\u00ED karet, tak\u017Ee dobr\u00FD fit nebo neobvykl\u00E9 rozlo\u017Een\u00ED m\u016F\u017Ee m\u00EDt mnohem v\u011Bt\u0161\u00ED hodnotu.",
              "Zp\u016Fsob porovn\u00E1n\u00ED z\u00E1vis\u00ED na z\u00E1pisu zvolen\u00E9m u stolu:",
              "- IMPy (v\u00FDchoz\u00ED): rozd\u00EDl od referen\u010Dn\u00EDho v\u00FDsledku se p\u0159evede na mezin\u00E1rodn\u00ED z\u00E1pasov\u00E9 body. Rozd\u00EDl do 10 bod\u016F nic nep\u0159inese, 20 a\u017E 40 je 1 IMP, 50 a\u017E 80 jsou 2 a 90 a\u017E 120 jsou 3. V\u011Bt\u0161\u00ED rozd\u00EDly p\u0159in\u00E1\u0161ej\u00ED v\u00EDc, ale pomaleji: 420 je 9 IMP\u016F a 4000 nebo v\u00EDce je maxim\u00E1ln\u00EDch 24. IMPy z\u00EDsk\u00E1 dvojice, kter\u00E1 dopadla l\u00E9pe ne\u017E referen\u010Dn\u00ED v\u00FDsledek.",
              "- Maxima: v ka\u017Ed\u00E9m rozd\u00E1n\u00ED z\u00EDsk\u00E1 dvojice, kter\u00E1 dopadla l\u00E9pe ne\u017E referen\u010Dn\u00ED v\u00FDsledek, 2 body a druh\u00E1 0; p\u0159i stejn\u00E9m v\u00FDsledku dostane ka\u017Ed\u00E1 dvojice 1. Kone\u010Dn\u00FD v\u00FDsledek je procento z bod\u016F, kter\u00E9 bylo mo\u017En\u00E9 z\u00EDskat.",
              "Rozd\u00E1n\u00ED, ve kter\u00E9m v\u0161ichni \u010Dty\u0159i pasovali, se tak\u00E9 po\u010D\u00EDt\u00E1: m\u00E1 v\u00FDsledek nula a porovn\u00E1 se s referen\u010Dn\u00EDm v\u00FDsledkem, tak\u017Ee pas se siln\u00FDmi kartami stoj\u00ED body. Po posledn\u00EDm rozd\u00E1n\u00ED vyhr\u00E1v\u00E1 dvojice s v\u00EDce IMPy nebo body; p\u0159i stejn\u00E9m sou\u010Dtu je rem\u00EDza. Kl\u00E1vesa S p\u0159e\u010Dte dosavadn\u00ED v\u00FDsledek."),
            rule_section(:bots, "Dra\u017Eba s po\u010D\u00EDta\u010Dov\u00FDm partnerem",
              "Po\u010D\u00EDta\u010Dov\u00ED hr\u00E1\u010Di vid\u00ED jen sv\u00E9 karty, st\u016Fl a hl\u00E1\u0161ky a karty, kter\u00E9 vid\u00ED v\u0161ichni. Dra\u017Euj\u00ED jednoduch\u00FDm p\u0159irozen\u00FDm syst\u00E9mem, d\u00EDky kter\u00E9mu jejich hl\u00E1\u0161k\u00E1m snadno porozum\u00ED\u0161:",
              "- 1 bez trumf\u016F znamen\u00E1 15 a\u017E 17 bod\u016F a vyrovnan\u00FD list, 2 bez trumf\u016F 20 nebo 21 bod\u016F.",
              "- Zah\u00E1jen\u00ED 1 srdce nebo 1 pik slibuje alespo\u0148 p\u011Bt karet v t\u00E9to barv\u011B a obvykle 12 nebo v\u00EDce bod\u016F. Bez p\u011Btilist\u00E9 drah\u00E9 barvy zah\u00E1j\u00ED bot 1 k\u00E1ro nebo 1 k\u0159\u00ED\u017E.",
              "- Zah\u00E1jen\u00ED 2 k\u00E1ra, 2 srdce nebo 2 piky je slab\u00E9: \u0161estilist\u00E1 barva a 6 a\u017E 10 bod\u016F.",
              "- Zv\u00FD\u0161en\u00ED tv\u00E9 barvy ukazuje podporu. Zv\u00FD\u0161en\u00ED na \u00FArove\u0148 2 je slab\u00E9, na 3 zve do hry a skok rovnou do hry ukazuje siln\u00FD list.",
              "Boti nikdy nekontruj\u00ED. Tak\u00E9 hraj\u00ED podle jednoduch\u00FDch pravidel: druh\u00FD hr\u00E1\u010D ve zdvihu p\u0159id\u00E1 n\u00EDzkou kartu, pokud nem\u00E1 jist\u00FD zdvih, dal\u0161\u00ED hr\u00E1\u010Di se sna\u017E\u00ED vz\u00EDt zdvih co nejni\u017E\u0161\u00ED kartou a obr\u00E1nce vyn\u00E1\u0161\u00ED v barv\u011B partnera nebo ve sv\u00E9 dlouh\u00E9 barv\u011B."),
            rule_section(:controls, "Kl\u00E1vesov\u00E9 zkratky",
              "Enter v seznamu hl\u00E1\u0161ek: pou\u017Eij vybranou hl\u00E1\u0161ku.",
              "B: vyber hl\u00E1\u0161ku, kdy\u017E jsi na \u0159ad\u011B, jinak p\u0159e\u010Dti dra\u017Ebu.",
              "L: p\u0159e\u010Dti dra\u017Ebu.",
              "Ctrl+L: proch\u00E1zej dra\u017Ebu.",
              "K: p\u0159e\u010Dti z\u00E1vazek a zdvihy hlavn\u00EDho hr\u00E1\u010De.",
              "Enter na kart\u011B: zahraj ji.",
              "Tab: p\u0159ejdi mezi sv\u00FDm listem a stolem.",
              "Z: p\u0159ejdi na dal\u0161\u00ED kartu, kterou lze zahr\u00E1t z listu, kter\u00FD je na \u0159ad\u011B; je-li jedin\u00E1, zahraj ji.",
              "Shift+Z: p\u0159ejdi na p\u0159edchoz\u00ED kartu, kterou lze zahr\u00E1t.",
              "H: p\u0159e\u010Dti sv\u016Fj list.",
              "D: p\u0159e\u010Dti list stolu.",
              "C: p\u0159e\u010Dti aktu\u00E1ln\u00ED zdvih.",
              "Ctrl+C: proch\u00E1zej aktu\u00E1ln\u00ED zdvih.",
              "F: p\u0159e\u010Dti vynesenou barvu.",
              "P: p\u0159e\u010Dti p\u0159edchoz\u00ED zdvih.",
              "V: p\u0159e\u010Dti rozd\u00E1n\u00ED, man\u0161e, z\u00E1vazek a zdvihy.",
              "I: p\u0159e\u010Dti sv\u00E9 m\u00EDsto, partnera a roli v tomto rozd\u00E1n\u00ED.",
              "S: p\u0159e\u010Dti v\u00FDsledky.",
              "T: p\u0159e\u010Dti, kdo je na \u0159ad\u011B.",
              "Shift+C: se\u0159a\u010F karty podle barvy.",
              "Shift+H: se\u0159a\u010F karty podle hodnoty.",
              "Shift+M: obnov p\u016Fvodn\u00ED po\u0159ad\u00ED karet.")
          ]
        when "en"
          [
            rule_section(:aim, "What the game is about",
              "Bridge is a card game for four players in two partnerships. You and your partner work together against the other pair. Each deal has two parts: first an auction, in which the pairs compete to name a contract, and then the play, in which the pair that won the contract tries to take at least as many tricks as it promised.",
              "Points come from making contracts and from defeating the opponents' contracts. The pair with more points when the match ends wins."),
            rule_section(:deal, "Partners and the deal",
              "The players are named after the points of the compass. North and South are partners, and so are East and West; partners sit opposite each other. When the table chooses teams, the two members of each team become partners. Play always moves clockwise: North, East, South, West.",
              "All 52 cards are dealt, so everyone gets 13. Press H to hear your hand suit by suit, from the highest card down, followed by your high card points: an ace counts 4, a king 3, a queen 2 and a jack 1. These points are not scored; they help you judge the strength of your hand during the auction. A whole deck holds 40 such points, so 10 is an average hand and 12 or more is usually enough to start the bidding.",
              "In every suit the ace is the highest card, followed by the king, queen, jack and ten down to the two."),
            rule_section(:auction, "The auction",
              "The dealer makes the first call and the others follow clockwise. When it is your turn, the game field shows a list of the calls you may make. Choose one with the arrow keys and press Enter. You can also press B to open the same list.",
              "A bid names a number of tricks and a trump suit, or no trump. The number is added to six: a bid of 1 heart promises 7 of the 13 tricks with hearts as trumps, and 4 spades promises 10 tricks with spades as trumps. Each bid must be higher than the previous one. A higher number always wins, and at the same number the suits rank from the lowest: clubs, diamonds, hearts, spades and no trump. After 1 spade you may bid 1 no trump or anything at the level of 2, but not 1 heart.",
              "Instead of bidding you can make one of these calls:",
              "- Pass: you do not want to bid now. Passing does not stop you from bidding later in the same auction.",
              "- Double: possible only right after an opponent's bid, or after an opponent's bid followed by passes. If that bid becomes the contract, it scores more for both sides: more for making it and more for defeating it.",
              "- Redouble: possible only after an opponent has doubled your side's bid. It raises the stakes once more.",
              "The auction ends when three players pass in a row after a bid. The last bid becomes the contract. If all four players pass at the start, nobody scores and the cards are dealt again by the next dealer.",
              "Press L to hear the whole auction, or Ctrl+L to go through it call by call."),
            rule_section(:contract, "Contract, declarer and dummy",
              "The pair that made the last bid must take the promised number of tricks; the other pair defends. The declarer is the player of the contracting pair who first bid the suit, or no trump, of the final contract. For example, if North opens 1 heart, South raises to 4 hearts and everyone passes, North is declarer even though South made the last bid.",
              "The player to the left of declarer leads the first card. Then declarer's partner becomes dummy: dummy's cards are laid face up for everyone, and declarer plays them as well as their own. Dummy takes no further part in the deal.",
              "Press K to hear the contract, who declares it and how many tricks declarer has taken so far."),
            rule_section(:play, "Playing the cards",
              "Each trick has four cards, one from each player in clockwise order. To play, go to a card in your hand with the arrow keys and press Enter. Z moves to the next card you are allowed to play and Shift+Z to the previous one; if you have only one playable card, Z plays it.",
              "You must follow the suit that was led if you can. If you have no card of that suit, you may play any card, including a trump, but you never have to trump. The highest trump in the trick wins it. If no trump was played, the highest card of the led suit wins. Cards of other suits cannot win the trick. The player who wins a trick leads to the next one.",
              "As declarer you also play dummy's cards. When it is dummy's turn, press Tab to move to the list of dummy's cards, or press Z, which goes straight to the cards dummy may play, and choose a card with Enter. Everyone can press D to hear dummy's hand.",
              "C reads the cards in the current trick and F the suit that was led. P repeats the previous trick, including who won it.",
              "After all 13 tricks the deal is scored, and the next deal starts with the next player clockwise as dealer."),
            rule_section(:scoring, "Points for the contract",
              "Only the tricks beyond the first six count. When declarer makes the contract, each contracted trick earns:",
              "- 20 points in clubs or diamonds;",
              "- 30 points in hearts or spades;",
              "- 40 points for the first trick in no trump and 30 for each further trick.",
              "These contract points are doubled if the contract was doubled and multiplied by four if it was redoubled. A contract worth at least 100 of them is a game: 3 no trump, 4 hearts, 4 spades, 5 clubs and 5 diamonds are the lowest games. A smaller contract is a part score.",
              "Being vulnerable raises both the rewards and the penalties. Who is vulnerable is announced at the start of each deal; V repeats it together with the deal number, the dealer, the contract and the tricks.",
              "Extra tricks are called overtricks. Without a double each one is worth the same as a contracted trick of that suit. Doubled, each overtrick earns 100, or 200 when vulnerable; redoubled, 200 or 400. Making a doubled contract adds 50 points, and a redoubled one 100.",
              "A small slam (a contract of 6) earns a bonus of 500, or 750 when vulnerable. A grand slam (a contract of 7) earns 1000, or 1500 when vulnerable.",
              "If declarer falls short, the defenders score for each missing trick:",
              "- not doubled: 50 per trick, or 100 when vulnerable;",
              "- doubled and not vulnerable: 100 for the first trick, 200 each for the second and third, and 300 for each further trick;",
              "- doubled and vulnerable: 200 for the first trick and 300 for each further trick;",
              "- redoubled: twice the doubled amount.",
              "For example, 2 spades doubled, not vulnerable, made with an overtrick earns 120 for the contract, 50 for making a doubled contract and 100 for the overtrick. The same contract two tricks short gives the defenders 300."),
            rule_section(:rubber, "Playing a rubber",
              "By default the table plays rubber bridge. A rubber ends when one pair has won two games, and the pair with more points in total wins the match. This is usually, but not always, the pair that won the rubber; equal totals are a draw.",
              "Contract points are written below the line and everything else above it. A game is won when a pair's points below the line reach 100, either in one deal or from several part scores. After a game, both pairs start the next game from zero below the line; part scores the opponents had towards that game no longer help them.",
              "A pair that has won a game is vulnerable for the rest of the rubber. Winning the rubber earns 700 if the opponents won no game and 500 if they won one.",
              "Honours are also scored above the line, whoever holds them, even a defender. Four of the five top trumps (ace, king, queen, jack, ten) in one hand earn 100 and all five earn 150. In no trump, all four aces in one hand earn 150. The table settings can turn honours off.",
              "S reads the points below and above the line, the games won and the total for each pair, followed by the score towards the current game."),
            rule_section(:duplicate, "Duplicate bridge",
              "In the table settings you can choose duplicate bridge instead. The match then lasts a set number of deals, called boards: 4, 8, 12, 16 or 24, with 8 by default. The board number decides the dealer and vulnerability, in the cycle used at bridge clubs. Board 1 is dealt by North with neither side vulnerable, board 2 by East with North-South vulnerable, board 3 by South with East-West vulnerable and board 4 by West with both sides vulnerable.",
              "Each board is scored on its own. A game earns a bonus of 300, or 500 when vulnerable, and a part score earns 50. Everything else is scored as described above. There are no honours and no rubber.",
              "In a club, the same boards are played at many tables and pairs compare their results. Here there is only one table, so your result is compared with a reference score: an estimate of what these cards usually earn, based on the combined high card points of the stronger pair. A pair with 20 points each scores nothing on average. With 23 points the stronger pair is expected to score 110, with 26 points 400, or 600 vulnerable, and with 33 points a slam of 980, or 1430 vulnerable. The estimate ignores the shape of the hands, so a good fit or an unusual distribution can be worth much more.",
              "How the comparison is counted depends on the table's scoring choice:",
              "- IMPs (the default): the difference from the reference score is converted into international match points. A difference of 10 or less is worth nothing, 20 to 40 is 1 IMP, 50 to 80 is 2 and 90 to 120 is 3. Larger swings earn more but more slowly: 420 is 9 IMPs and 4000 or more is the maximum of 24. The pair that did better than the reference gains the IMPs.",
              "- Matchpoints: on each board the pair that did better than the reference earns 2 points and the other pair 0; an equal result gives each pair 1. The final score is the percentage of the available points.",
              "A board passed out by all four players also counts: it scores zero and is compared with the reference, so passing with strong cards loses points. After the last board, the pair with more IMPs or matchpoints wins; an equal total is a draw. S reads the totals so far."),
            rule_section(:bots, "Bidding with a computer partner",
              "Computer players see only their own cards, dummy and the calls and cards everyone else can see. They bid a simple natural system, which helps you understand their calls:",
              "- 1 no trump shows 15 to 17 points and a balanced hand; 2 no trump shows 20 or 21.",
              "- An opening bid of 1 heart or 1 spade promises at least five cards in that suit and usually 12 or more points. Without a five-card major, a bot opens 1 diamond or 1 club.",
              "- An opening bid of 2 diamonds, 2 hearts or 2 spades is weak: a six-card suit with 6 to 10 points.",
              "- A raise of your suit shows support. A raise to the level of 2 is weak, a raise to 3 invites game, and a jump to game is a strong hand.",
              "Bots never double. They play by simple rules too: the second player to a trick plays low unless it holds a sure winner, later players try to win the trick as cheaply as possible, and a defender leads partner's suit or a long suit."),
            rule_section(:controls, "Keyboard shortcuts",
              "Enter in the list of calls: make the selected call.",
              "B: choose a call when it is your turn, otherwise read the auction.",
              "L: read the auction.",
              "Ctrl+L: browse the auction.",
              "K: read the contract and declarer's tricks.",
              "Enter on a card: play it.",
              "Tab: move between your hand and dummy.",
              "Z: go to the next playable card in the hand that is to play; play it if it is the only one.",
              "Shift+Z: go to the previous playable card.",
              "H: read your hand.",
              "D: read dummy's hand.",
              "C: read the current trick.",
              "Ctrl+C: browse the current trick.",
              "F: read the led suit.",
              "P: read the previous trick.",
              "V: read the deal, vulnerability, contract and tricks.",
              "I: read your seat, partner and role in this deal.",
              "S: read the scores.",
              "T: read whose turn it is.",
              "Shift+C: sort your cards by suit.",
              "Shift+H: sort your cards by rank.",
              "Shift+M: restore the order in which you received your cards.")
          ]
        when "es"
          [
            rule_section(:aim, "En qu\u00E9 consiste el juego",
              "El bridge es un juego de cartas para cuatro personas que juegan en dos parejas. Juegas junto a tu compa\u00F1ero contra la otra pareja. Cada mano tiene dos partes: primero la subasta, en la que las parejas compiten por fijar un contrato, y despu\u00E9s el carteo, en el que la pareja que gan\u00F3 el contrato intenta hacer al menos las bazas que prometi\u00F3.",
              "Se consiguen puntos cumpliendo contratos y haciendo fallar los contratos de los rivales. Gana la pareja que tenga m\u00E1s puntos al terminar el encuentro."),
            rule_section(:deal, "Parejas y reparto",
              "Los puestos se llaman como los puntos cardinales. Norte juega con Sur y Este con Oeste; los compa\u00F1eros se sientan uno frente al otro. Si en la mesa se eligen equipos, los dos miembros de cada equipo son compa\u00F1eros. El juego siempre avanza en el sentido de las agujas del reloj: Norte, Este, Sur, Oeste.",
              "Se reparten las 52 cartas, as\u00ED que cada uno recibe 13. Pulsa H para escuchar tu mano palo por palo, de la carta m\u00E1s alta a la m\u00E1s baja, y al final tus puntos de honor: el as vale 4, el rey 3, la dama 2 y la jota 1. Estos puntos no se anotan, pero te ayudan a valorar la fuerza de tu mano durante la subasta. La baraja entera tiene 40, de modo que una mano media tiene 10 y con 12 o m\u00E1s suele bastar para abrir.",
              "En cada palo la carta m\u00E1s alta es el as, seguido del rey, la dama, la jota, el diez y las dem\u00E1s hasta el dos."),
            rule_section(:auction, "La subasta",
              "Empieza a hablar quien reparte y los dem\u00E1s siguen en el sentido de las agujas del reloj. Cuando te toca, en el campo de juego aparece la lista de voces que puedes dar. Elige una con las flechas y pulsa Enter. Tambi\u00E9n puedes abrir la misma lista con la tecla B.",
              "Una declaraci\u00F3n indica un n\u00FAmero de bazas y un palo de triunfo, o sin triunfo. Al n\u00FAmero se le suman seis: 1 coraz\u00F3n promete 7 de las 13 bazas con corazones como triunfo y 4 picas promete 10 bazas con picas como triunfo. Cada declaraci\u00F3n tiene que ser m\u00E1s alta que la anterior. Un n\u00FAmero mayor siempre supera a uno menor y, con el mismo n\u00FAmero, los palos van de menor a mayor: tr\u00E9boles, diamantes, corazones, picas y sin triunfo. Despu\u00E9s de 1 pica puedes declarar 1 sin triunfo o cualquier voz de nivel 2, pero no 1 coraz\u00F3n.",
              "En lugar de declarar puedes dar una de estas voces:",
              "- Paso: no quieres declarar ahora. Pasar no te impide declarar m\u00E1s tarde en la misma subasta.",
              "- Doblo: solo es posible despu\u00E9s de una declaraci\u00F3n de un rival, aunque detr\u00E1s hayan venido pasos. Si esa declaraci\u00F3n se convierte en el contrato, ambas partes ganan m\u00E1s: el declarante por cumplirlo y los defensores por hacerlo fallar.",
              "- Redoblo: solo es posible cuando un rival ha doblado una declaraci\u00F3n de tu pareja. Vuelve a subir lo que est\u00E1 en juego.",
              "La subasta termina cuando, despu\u00E9s de una declaraci\u00F3n, pasan tres jugadores seguidos. La \u00FAltima declaraci\u00F3n es el contrato. Si al principio pasan los cuatro, nadie punt\u00FAa y el siguiente jugador vuelve a repartir.",
              "Pulsa L para escuchar toda la subasta o Ctrl+L para recorrerla voz por voz."),
            rule_section(:contract, "Contrato, declarante y muerto",
              "La pareja que dio la \u00FAltima declaraci\u00F3n tiene que hacer las bazas prometidas y la otra defiende. El declarante es el jugador de esa pareja que nombr\u00F3 primero el palo del contrato, o el sin triunfo. Por ejemplo, si Norte abre 1 coraz\u00F3n, Sur sube a 4 corazones y todos pasan, juega Norte, aunque la \u00FAltima declaraci\u00F3n la dio Sur.",
              "La primera carta, la salida, la juega quien est\u00E1 a la izquierda del declarante. Entonces el compa\u00F1ero del declarante pasa a ser el muerto: sus cartas quedan boca arriba para todos y el declarante las juega igual que las suyas. El muerto ya no participa en esa mano.",
              "Pulsa K para saber el contrato, qui\u00E9n lo juega y cu\u00E1ntas bazas lleva ya el declarante."),
            rule_section(:play, "El carteo",
              "Cada baza tiene cuatro cartas, una de cada jugador en el sentido de las agujas del reloj. Para jugar, ve con las flechas a una carta de tu mano y pulsa Enter. Z te lleva a la siguiente carta que puedes jugar y Shift+Z a la anterior; si solo puedes jugar una carta, Z la juega directamente.",
              "Si tienes cartas del palo de salida, tienes que servir ese palo. Si no tienes, puedes jugar cualquier carta, tambi\u00E9n un triunfo, pero nunca est\u00E1s obligado a fallar. Gana la baza el triunfo m\u00E1s alto y, si nadie ha jugado triunfo, la carta m\u00E1s alta del palo de salida. Las cartas de otros palos no pueden ganar la baza. Quien gana una baza sale en la siguiente.",
              "Como declarante tambi\u00E9n juegas las cartas del muerto. Cuando le toca al muerto, pulsa Tab para pasar a la lista de sus cartas, o pulsa Z, que te lleva directamente a las cartas que puede jugar el muerto, y elige una con Enter. Cualquiera puede escuchar la mano del muerto con D.",
              "C lee las cartas de la baza actual y F el palo de salida. P repite la baza anterior y qui\u00E9n la gan\u00F3.",
              "Cuando se han jugado las 13 bazas se punt\u00FAa la mano, y la siguiente la reparte el jugador siguiente en el sentido de las agujas del reloj."),
            rule_section(:scoring, "Puntos del contrato",
              "Solo cuentan las bazas que pasan de las seis primeras. Cuando el declarante cumple el contrato, cada baza contratada vale:",
              "- 20 puntos en tr\u00E9boles o diamantes;",
              "- 30 puntos en corazones o picas;",
              "- 40 puntos la primera baza a sin triunfo y 30 cada una de las siguientes.",
              "Estos puntos del contrato se duplican si el contrato estaba doblado y se multiplican por cuatro si estaba redoblado. Un contrato que vale al menos 100 de estos puntos es una manga: las mangas m\u00E1s bajas son 3 sin triunfo, 4 corazones, 4 picas, 5 tr\u00E9boles y 5 diamantes. Un contrato menor es un parcial.",
              "Ser vulnerable aumenta tanto los premios como las penalizaciones. Al empezar cada mano se anuncia qui\u00E9n es vulnerable; V lo repite junto con el n\u00FAmero de mano, qui\u00E9n reparte, el contrato y las bazas.",
              "Las bazas de m\u00E1s se llaman sobrebazas. Sin doblo, cada una vale lo mismo que una baza contratada de ese palo. Doblada, cada sobrebaza vale 100, o 200 si se es vulnerable; redoblada, 200 o 400. Cumplir un contrato doblado a\u00F1ade 50 puntos, y uno redoblado, 100.",
              "Un peque\u00F1o slam, un contrato de nivel 6, da un premio de 500, o 750 vulnerable. Un gran slam, un contrato de nivel 7, da 1000, o 1500 vulnerable.",
              "Si el declarante se queda corto, los defensores punt\u00FAan por cada baza que falta, es decir, por cada multa:",
              "- sin doblo: 50 por baza, o 100 si el declarante es vulnerable;",
              "- doblado y no vulnerable: 100 por la primera baza, 200 por la segunda y la tercera y 300 por cada una de las siguientes;",
              "- doblado y vulnerable: 200 por la primera baza y 300 por cada una de las siguientes;",
              "- redoblado: el doble que con doblo.",
              "Por ejemplo, 2 picas dobladas, no vulnerable, cumplidas con una sobrebaza dan 120 por el contrato, 50 por cumplir un contrato doblado y 100 por la sobrebaza. El mismo contrato con dos multas da 300 a los defensores."),
            rule_section(:rubber, "Jugar un robber",
              "Por defecto, en la mesa se juega al bridge de robber. El robber termina cuando una pareja gana dos mangas, y gana el encuentro la pareja con m\u00E1s puntos en total. Normalmente es la que gan\u00F3 el robber, pero no siempre; con totales iguales hay empate.",
              "Los puntos del contrato se anotan debajo de la raya y todos los dem\u00E1s encima. Una pareja gana una manga cuando sus puntos debajo de la raya llegan a 100, en una sola mano o sumando varios parciales. Despu\u00E9s de una manga, las dos parejas empiezan la siguiente desde cero debajo de la raya; los parciales que los rivales ten\u00EDan hacia esa manga ya no les sirven.",
              "La pareja que ha ganado una manga es vulnerable hasta el final del robber. Ganar el robber da 700 puntos si los rivales no ganaron ninguna manga y 500 si ganaron una.",
              "Los honores tambi\u00E9n se anotan encima de la raya, los tenga quien los tenga, aunque sea un defensor. Cuatro de los cinco triunfos m\u00E1s altos (as, rey, dama, jota y diez) en una misma mano dan 100, y los cinco, 150. A sin triunfo, los cuatro ases en una misma mano dan 150. Los honores se pueden desactivar en los ajustes de la mesa.",
              "S lee los puntos debajo y encima de la raya, las mangas ganadas y el total de cada pareja, y despu\u00E9s c\u00F3mo va la manga en curso."),
            rule_section(:duplicate, "Bridge duplicado",
              "En los ajustes de la mesa puedes elegir en su lugar el bridge duplicado. El encuentro dura entonces un n\u00FAmero fijo de manos: 4, 8, 12, 16 o 24, con 8 por defecto. El n\u00FAmero de mano fija qui\u00E9n reparte y la vulnerabilidad, con el mismo ciclo que en los clubes. La mano 1 la reparte Norte sin nadie vulnerable, la 2 Este con Norte-Sur vulnerables, la 3 Sur con Este-Oeste vulnerables y la 4 Oeste con todos vulnerables.",
              "Cada mano se punt\u00FAa por separado. Una manga da un premio de 300, o 500 vulnerable, y un parcial 50. Todo lo dem\u00E1s se cuenta como se ha explicado antes. No hay honores ni robber.",
              "En un club, las mismas manos se juegan en muchas mesas y las parejas comparan sus resultados. Aqu\u00ED solo hay una mesa, as\u00ED que tu resultado se compara con un resultado de referencia: una estimaci\u00F3n de lo que suelen dar esas cartas, seg\u00FAn la suma de puntos de honor de la pareja m\u00E1s fuerte. Si cada pareja tiene 20 puntos, la referencia es cero. Con 23 puntos la pareja m\u00E1s fuerte deber\u00EDa anotar 110, con 26 puntos 400, o 600 vulnerable, y con 33 puntos un peque\u00F1o slam de 980, o 1430 vulnerable. La estimaci\u00F3n no tiene en cuenta la distribuci\u00F3n, as\u00ED que un buen fit o un reparto poco habitual pueden valer mucho m\u00E1s.",
              "La comparaci\u00F3n depende de la puntuaci\u00F3n elegida en la mesa:",
              "- IMP (por defecto): la diferencia con el resultado de referencia se convierte en puntos internacionales de match. Una diferencia de 10 o menos no vale nada, de 20 a 40 es 1 IMP, de 50 a 80 son 2 y de 90 a 120 son 3. Las diferencias mayores dan m\u00E1s, pero cada vez m\u00E1s despacio: 420 son 9 IMP y 4000 o m\u00E1s es el m\u00E1ximo de 24. Gana los IMP la pareja que mejor\u00F3 el resultado de referencia.",
              "- Por porcentaje: en cada mano, la pareja que mejor\u00F3 el resultado de referencia recibe 2 puntos y la otra 0; con el mismo resultado, cada pareja recibe 1. El resultado final es el porcentaje de los puntos posibles.",
              "Una mano en la que pasan los cuatro tambi\u00E9n cuenta: vale cero y se compara con la referencia, as\u00ED que pasar con cartas fuertes cuesta puntos. Despu\u00E9s de la \u00FAltima mano gana la pareja con m\u00E1s IMP o puntos; con el mismo total hay empate. S lee el resultado hasta el momento."),
            rule_section(:bots, "Subastar con un compa\u00F1ero del ordenador",
              "Los jugadores del ordenador solo ven sus cartas, el muerto y las voces y cartas que ve todo el mundo. Subastan con un sistema natural sencillo, lo que te ayuda a entender sus voces:",
              "- 1 sin triunfo indica de 15 a 17 puntos y una mano equilibrada; 2 sin triunfo, 20 o 21.",
              "- Una apertura de 1 coraz\u00F3n o 1 pica promete al menos cinco cartas de ese palo y normalmente 12 puntos o m\u00E1s. Sin un palo mayor de cinco cartas, el bot abre de 1 diamante o 1 tr\u00E9bol.",
              "- Una apertura de 2 diamantes, 2 corazones o 2 picas es d\u00E9bil: un palo de seis cartas y de 6 a 10 puntos.",
              "- Subir tu palo muestra apoyo. Subir a nivel 2 es d\u00E9bil, a 3 invita a manga y saltar directamente a manga indica una mano fuerte.",
              "Los bots nunca doblan. Tambi\u00E9n juegan con reglas sencillas: el segundo jugador de la baza juega bajo salvo que tenga una baza segura, los siguientes intentan ganar la baza con la carta m\u00E1s baja posible y un defensor sale del palo de su compa\u00F1ero o de su palo largo."),
            rule_section(:controls, "Atajos de teclado",
              "Enter en la lista de voces: dar la voz elegida.",
              "B: elegir una voz cuando te toca; en otro momento, leer la subasta.",
              "L: leer la subasta.",
              "Ctrl+L: recorrer la subasta.",
              "K: leer el contrato y las bazas del declarante.",
              "Enter sobre una carta: jugarla.",
              "Tab: pasar entre tu mano y el muerto.",
              "Z: ir a la siguiente carta jugable de la mano a la que le toca; si es la \u00FAnica, jugarla.",
              "Shift+Z: ir a la carta jugable anterior.",
              "H: leer tu mano.",
              "D: leer la mano del muerto.",
              "C: leer la baza actual.",
              "Ctrl+C: recorrer la baza actual.",
              "F: leer el palo de salida.",
              "P: leer la baza anterior.",
              "V: leer la mano, la vulnerabilidad, el contrato y las bazas.",
              "I: leer tu puesto, tu compa\u00F1ero y tu papel en esta mano.",
              "S: leer la puntuaci\u00F3n.",
              "T: leer a qui\u00E9n le toca.",
              "Shift+C: ordenar las cartas por palo.",
              "Shift+H: ordenar las cartas por valor.",
              "Shift+M: recuperar el orden original de las cartas.")
          ]
        when "pl"
          [
            rule_section(:aim, "Na czym polega gra",
              "Bryd\u017C to gra karciana dla czterech os\u00F3b graj\u0105cych w dw\u00F3ch parach. Ty i tw\u00F3j partner gracie razem przeciwko drugiej parze. Ka\u017Cde rozdanie ma dwie cz\u0119\u015Bci: najpierw licytacj\u0119, w kt\u00F3rej pary rywalizuj\u0105 o kontrakt, a potem rozgrywk\u0119, w kt\u00F3rej para, kt\u00F3ra wylicytowa\u0142a kontrakt, pr\u00F3buje wzi\u0105\u0107 co najmniej tyle lew, ile zapowiedzia\u0142a.",
              "Punkty zdobywa si\u0119 za wype\u0142nione kontrakty i za ob\u0142o\u017Cenie kontrakt\u00F3w przeciwnik\u00F3w. Wygrywa para, kt\u00F3ra na koniec meczu ma wi\u0119cej punkt\u00F3w."),
            rule_section(:deal, "Pary i rozdanie",
              "Miejsca przy stole nazywa si\u0119 jak strony \u015Bwiata. P\u00F3\u0142noc gra w parze z Po\u0142udniem, a Wsch\u00F3d z Zachodem; partnerzy siedz\u0105 naprzeciw siebie. Je\u015Bli przy stole wybrano dru\u017Cyny, dwie osoby z jednej dru\u017Cyny s\u0105 partnerami. Gra zawsze toczy si\u0119 zgodnie z ruchem wskaz\u00F3wek zegara: P\u00F3\u0142noc, Wsch\u00F3d, Po\u0142udnie, Zach\u00F3d.",
              "Rozdaje si\u0119 wszystkie 52 karty, wi\u0119c ka\u017Cdy dostaje 13. Klawiszem H odczytasz swoj\u0105 r\u0119k\u0119 kolor po kolorze, od najstarszej karty, a na ko\u0144cu liczb\u0119 punkt\u00F3w honorowych: as to 4 punkty, kr\u00F3l 3, dama 2, a walet 1. Tych punkt\u00F3w nie wpisuje si\u0119 do zapisu, ale pomagaj\u0105 oceni\u0107 si\u0142\u0119 r\u0119ki w licytacji. W ca\u0142ej talii jest ich 40, wi\u0119c przeci\u0119tna r\u0119ka ma 10 punkt\u00F3w, a 12 lub wi\u0119cej zwykle wystarcza do otwarcia licytacji.",
              "W ka\u017Cdym kolorze najstarszy jest as, potem kr\u00F3l, dama, walet, dziesi\u0105tka i kolejne blotki a\u017C do dw\u00F3jki."),
            rule_section(:auction, "Licytacja",
              "Licytacj\u0119 zaczyna rozdaj\u0105cy, a pozostali m\u00F3wi\u0105 po kolei zgodnie z ruchem wskaz\u00F3wek zegara. Gdy przyjdzie twoja kolej, w polu gry pojawi si\u0119 lista dozwolonych zapowiedzi. Wybierz zapowied\u017A strza\u0142kami i naci\u015Bnij Enter. T\u0119 sam\u0105 list\u0119 otworzysz te\u017C klawiszem B.",
              "Odzywka okre\u015Bla liczb\u0119 lew i kolor atutowy albo gr\u0119 bez atu. Do podanej liczby dodaje si\u0119 sze\u015B\u0107: odzywka 1 kier zapowiada 7 z 13 lew z kierami w atucie, a 4 piki \u2014 10 lew z pikami w atucie. Ka\u017Cda odzywka musi by\u0107 wy\u017Csza od poprzedniej. Wy\u017Csza liczba zawsze przebija ni\u017Csz\u0105, a przy tej samej liczbie kolory s\u0105 uporz\u0105dkowane od najm\u0142odszego: trefle, kara, kiery, piki i bez atu. Po 1 piku mo\u017Cesz powiedzie\u0107 1 bez atu albo dowoln\u0105 odzywk\u0119 na wysoko\u015Bci 2, ale nie 1 kier.",
              "Zamiast odzywki mo\u017Cesz zg\u0142osi\u0107 jedn\u0105 z tych zapowiedzi:",
              "- Pas: nie chcesz teraz licytowa\u0107. Pas nie przeszkadza ci odezwa\u0107 si\u0119 p\u00F3\u017Aniej w tej samej licytacji.",
              "- Kontra: dozwolona tylko po odzywce przeciwnika, tak\u017Ce wtedy, gdy po niej pad\u0142y pasy. Je\u015Bli ta odzywka zostanie kontraktem, obie strony zdobywaj\u0105 wi\u0119cej: rozgrywaj\u0105cy za jego wype\u0142nienie, a obro\u0144cy za wpadk\u0119.",
              "- Rekontra: dozwolona tylko wtedy, gdy przeciwnik skontrowa\u0142 odzywk\u0119 twojej pary. Jeszcze raz podnosi stawk\u0119.",
              "Licytacja ko\u0144czy si\u0119, gdy po odzywce trzech graczy z rz\u0119du spasuje. Ostatnia odzywka staje si\u0119 kontraktem. Je\u015Bli na pocz\u0105tku spasuj\u0105 wszyscy czterej, nikt nie dostaje punkt\u00F3w, a karty rozdaje od nowa nast\u0119pny gracz.",
              "Klawisz L odczytuje ca\u0142\u0105 licytacj\u0119, a Ctrl+L pozwala przejrze\u0107 j\u0105 zapowied\u017A po zapowiedzi."),
            rule_section(:contract, "Kontrakt, rozgrywaj\u0105cy i dziadek",
              "Para, kt\u00F3ra zg\u0142osi\u0142a ostatni\u0105 odzywk\u0119, musi wzi\u0105\u0107 zapowiedzian\u0105 liczb\u0119 lew, a druga para si\u0119 broni. Rozgrywaj\u0105cym zostaje ten z graczy tej pary, kt\u00F3ry jako pierwszy wymieni\u0142 kolor kontraktu albo bez atu. Je\u015Bli na przyk\u0142ad P\u00F3\u0142noc otworzy 1 kier, Po\u0142udnie podniesie do 4 kier\u00F3w, a wszyscy spasuj\u0105, rozgrywa P\u00F3\u0142noc, cho\u0107 ostatni\u0105 odzywk\u0119 zg\u0142osi\u0142o Po\u0142udnie.",
              "Pierwsz\u0105 kart\u0119, czyli wist, wychodzi gracz siedz\u0105cy na lewo od rozgrywaj\u0105cego. Wtedy partner rozgrywaj\u0105cego zostaje dziadkiem: jego karty le\u017C\u0105 odkryte dla wszystkich, a rozgrywaj\u0105cy gra nimi tak samo jak w\u0142asnymi. Dziadek nie bierze ju\u017C udzia\u0142u w tym rozdaniu.",
              "Klawisz K podaje kontrakt, rozgrywaj\u0105cego i liczb\u0119 lew, kt\u00F3re rozgrywaj\u0105cy ju\u017C wzi\u0105\u0142."),
            rule_section(:play, "Rozgrywka",
              "Ka\u017Cda lewa sk\u0142ada si\u0119 z czterech kart, po jednej od ka\u017Cdego gracza zgodnie z ruchem wskaz\u00F3wek zegara. \u017Beby zagra\u0107, przejd\u017A strza\u0142kami do karty w swojej r\u0119ce i naci\u015Bnij Enter. Klawisz Z przenosi ci\u0119 do nast\u0119pnej karty, kt\u00F3r\u0105 wolno ci zagra\u0107, a Shift+Z do poprzedniej; je\u015Bli mo\u017Cesz zagra\u0107 tylko jedn\u0105 kart\u0119, Z od razu j\u0105 zagrywa.",
              "Je\u015Bli masz karty koloru wyj\u015Bcia, musisz do\u0142o\u017Cy\u0107 do koloru. Gdy go nie masz, mo\u017Cesz zagra\u0107 dowoln\u0105 kart\u0119, tak\u017Ce atut, ale nigdy nie musisz przebija\u0107. Lew\u0119 bierze najwy\u017Cszy atut, a je\u015Bli nikt nie zagra\u0142 atutu \u2014 najwy\u017Csza karta koloru wyj\u015Bcia. Karty innych kolor\u00F3w nie mog\u0105 wzi\u0105\u0107 lewy. Gracz, kt\u00F3ry wzi\u0105\u0142 lew\u0119, wychodzi do nast\u0119pnej.",
              "Jako rozgrywaj\u0105cy grasz te\u017C kartami dziadka. Gdy przyjdzie kolej dziadka, naci\u015Bnij Tab, \u017Ceby przej\u015B\u0107 do listy jego kart, albo Z, kt\u00F3re od razu ustawia ci\u0119 na kartach, jakie dziadek mo\u017Ce zagra\u0107, i wybierz kart\u0119 Enterem. R\u0119k\u0119 dziadka mo\u017Ce w ka\u017Cdej chwili odczyta\u0107 ka\u017Cdy gracz klawiszem D.",
              "Klawisz C odczytuje karty bie\u017C\u0105cej lewy, a F kolor wyj\u015Bcia. P powtarza poprzedni\u0105 lew\u0119 razem z tym, kto j\u0105 wzi\u0105\u0142.",
              "Po rozegraniu wszystkich 13 lew rozdanie zostaje policzone, a nast\u0119pne rozdaje kolejny gracz zgodnie z ruchem wskaz\u00F3wek zegara."),
            rule_section(:scoring, "Punkty za kontrakt",
              "Licz\u0105 si\u0119 tylko lewy ponad pierwsze sze\u015B\u0107. Gdy rozgrywaj\u0105cy wype\u0142ni kontrakt, ka\u017Cda zakontraktowana lewa jest warta:",
              "- 20 punkt\u00F3w w treflach lub karach;",
              "- 30 punkt\u00F3w w kierach lub pikach;",
              "- 40 punkt\u00F3w za pierwsz\u0105 lew\u0119 w bez atu i po 30 za ka\u017Cd\u0105 nast\u0119pn\u0105.",
              "Te punkty za kontrakt podwaja si\u0119, je\u015Bli kontrakt by\u0142 skontrowany, i mno\u017Cy przez cztery po rekontrze. Kontrakt warty co najmniej 100 takich punkt\u00F3w to ko\u0144c\u00F3wka: najni\u017Csze ko\u0144c\u00F3wki to 3 bez atu, 4 kiery, 4 piki, 5 trefli i 5 kar. Mniejszy kontrakt to cz\u0119\u015Bci\u00F3wka.",
              "Gra po partii podnosi zar\u00F3wno premie, jak i kary. Na pocz\u0105tku ka\u017Cdego rozdania s\u0142ycha\u0107, kto jest po partii, a kto przed parti\u0105; klawisz V powtarza t\u0119 informacj\u0119 razem z numerem rozdania, rozdaj\u0105cym, kontraktem i lewami.",
              "Lewy ponad kontrakt to nadr\u00F3bki. Bez kontry ka\u017Cda jest warta tyle co zakontraktowana lewa w tym kolorze. Po kontrze ka\u017Cda nadr\u00F3bka daje 100 punkt\u00F3w, a po partii 200; po rekontrze 200 albo 400. Za wype\u0142nienie skontrowanego kontraktu dochodzi 50 punkt\u00F3w, a zrekontrowanego \u2014 100.",
              "Szlemik, czyli kontrakt na wysoko\u015Bci 6, daje premi\u0119 500, a po partii 750. Szlem, czyli kontrakt na wysoko\u015Bci 7, daje 1000, a po partii 1500.",
              "Je\u015Bli rozgrywaj\u0105cy we\u017Amie za ma\u0142o lew, obro\u0144cy dostaj\u0105 punkty za ka\u017Cd\u0105 brakuj\u0105c\u0105 lew\u0119, czyli wpadk\u0119:",
              "- bez kontry: po 50 za lew\u0119, a po partii po 100;",
              "- z kontr\u0105 przed parti\u0105: 100 za pierwsz\u0105 wpadk\u0119, po 200 za drug\u0105 i trzeci\u0105 i po 300 za ka\u017Cd\u0105 nast\u0119pn\u0105;",
              "- z kontr\u0105 po partii: 200 za pierwsz\u0105 wpadk\u0119 i po 300 za ka\u017Cd\u0105 nast\u0119pn\u0105;",
              "- z rekontr\u0105: dwa razy wi\u0119cej ni\u017C z kontr\u0105.",
              "Na przyk\u0142ad 2 piki z kontr\u0105 przed parti\u0105 wype\u0142nione z nadr\u00F3bk\u0105 daj\u0105 120 za kontrakt, 50 za wype\u0142nienie skontrowanego kontraktu i 100 za nadr\u00F3bk\u0119. Ten sam kontrakt z dwiema wpadkami daje obro\u0144com 300."),
            rule_section(:rubber, "Gra na robra",
              "Domy\u015Blnie przy stole gra si\u0119 na robra. Robr ko\u0144czy si\u0119, gdy jedna para wygra dwie partie, a mecz wygrywa para z wi\u0119ksz\u0105 \u0142\u0105czn\u0105 liczb\u0105 punkt\u00F3w. Zwykle jest to para, kt\u00F3ra wygra\u0142a robra, ale nie zawsze; przy r\u00F3wnych sumach jest remis.",
              "Punkty za kontrakt zapisuje si\u0119 pod kresk\u0105, a wszystkie pozosta\u0142e nad kresk\u0105. Parti\u0119 wygrywa para, kt\u00F3rej punkty pod kresk\u0105 osi\u0105gn\u0105 100 \u2014 w jednym rozdaniu albo z kilku cz\u0119\u015Bci\u00F3wek. Po wygranej partii obie pary zaczynaj\u0105 nast\u0119pn\u0105 od zera pod kresk\u0105; cz\u0119\u015Bci\u00F3wki, kt\u00F3re przeciwnicy mieli w poprzedniej partii, ju\u017C im nie pomagaj\u0105.",
              "Para, kt\u00F3ra wygra\u0142a parti\u0119, jest po partii do ko\u0144ca robra. Za wygranie robra dostaje si\u0119 700 punkt\u00F3w, je\u015Bli przeciwnicy nie wygrali \u017Cadnej partii, i 500, je\u015Bli wygrali jedn\u0105.",
              "Nad kresk\u0105 zapisuje si\u0119 te\u017C honory, niezale\u017Cnie od tego, kto je ma, nawet obro\u0144ca. Cztery z pi\u0119ciu najstarszych atut\u00F3w (as, kr\u00F3l, dama, walet, dziesi\u0105tka) w jednej r\u0119ce daj\u0105 100, a wszystkie pi\u0119\u0107 \u2014 150. W bez atu wszystkie cztery asy w jednej r\u0119ce daj\u0105 150. Liczenie honor\u00F3w mo\u017Cna wy\u0142\u0105czy\u0107 w ustawieniach sto\u0142u.",
              "Klawisz S odczytuje punkty pod kresk\u0105 i nad kresk\u0105, wygrane partie i sum\u0119 ka\u017Cdej pary, a potem stan bie\u017C\u0105cej partii."),
            rule_section(:duplicate, "Bryd\u017C sportowy",
              "W ustawieniach sto\u0142u mo\u017Cesz zamiast tego wybra\u0107 bryd\u017C sportowy. Mecz trwa wtedy ustalon\u0105 liczb\u0119 rozda\u0144: 4, 8, 12, 16 albo 24, domy\u015Blnie 8. Numer rozdania wyznacza rozdaj\u0105cego i za\u0142o\u017Cenia, w takim samym cyklu jak w klubach bryd\u017Cowych. Rozdanie 1 rozdaje P\u00F3\u0142noc i obie pary s\u0105 przed parti\u0105, rozdanie 2 Wsch\u00F3d przy za\u0142o\u017Ceniach po partii dla P\u00F3\u0142nocy i Po\u0142udnia, rozdanie 3 Po\u0142udnie przy za\u0142o\u017Ceniach po partii dla Wschodu i Zachodu, a rozdanie 4 Zach\u00F3d, gdy obie pary s\u0105 po partii.",
              "Ka\u017Cde rozdanie liczy si\u0119 osobno. Ko\u0144c\u00F3wka daje premi\u0119 300, a po partii 500, a cz\u0119\u015Bci\u00F3wka 50. Wszystko inne liczy si\u0119 tak, jak opisano wy\u017Cej. Nie ma honor\u00F3w ani robra.",
              "W klubie te same rozdania gra si\u0119 przy wielu sto\u0142ach i pary por\u00F3wnuj\u0105 swoje wyniki. Tu jest tylko jeden st\u00F3\u0142, wi\u0119c tw\u00F3j wynik por\u00F3wnuje si\u0119 z wynikiem odniesienia: szacunkiem, ile zwykle przynosz\u0105 takie karty, liczonym z sumy punkt\u00F3w honorowych silniejszej pary. Gdy obie pary maj\u0105 po 20 punkt\u00F3w, wynik odniesienia wynosi zero. Przy 23 punktach silniejsza para powinna zdoby\u0107 110, przy 26 punktach 400, a po partii 600, a przy 33 punktach \u2014 szlemika za 980, a po partii 1430. Szacunek nie uwzgl\u0119dnia uk\u0142adu kart, wi\u0119c dobry fit albo nietypowy rozk\u0142ad mo\u017Ce by\u0107 wart du\u017Co wi\u0119cej.",
              "Spos\u00F3b por\u00F3wnania zale\u017Cy od zapisu wybranego przy stole:",
              "- IMP-y (domy\u015Blnie): r\u00F3\u017Cnic\u0119 wzgl\u0119dem wyniku odniesienia przelicza si\u0119 na mi\u0119dzynarodowe punkty meczowe. R\u00F3\u017Cnica do 10 punkt\u00F3w nic nie daje, od 20 do 40 to 1 IMP, od 50 do 80 to 2, a od 90 do 120 to 3. Wi\u0119ksze r\u00F3\u017Cnice daj\u0105 coraz wi\u0119cej, ale wolniej: 420 to 9 IMP-\u00F3w, a 4000 lub wi\u0119cej to maksymalne 24. IMP-y dostaje para, kt\u00F3ra wypad\u0142a lepiej od wyniku odniesienia.",
              "- Zapis maksymalny: w ka\u017Cdym rozdaniu para, kt\u00F3ra wypad\u0142a lepiej od wyniku odniesienia, dostaje 2 punkty, a druga 0; przy r\u00F3wnym wyniku ka\u017Cda para dostaje 1. Wynikiem ko\u0144cowym jest procent mo\u017Cliwych do zdobycia punkt\u00F3w.",
              "Rozdanie, w kt\u00F3rym wszyscy czterej spasowali, te\u017C si\u0119 liczy: ma wynik zero i por\u00F3wnuje si\u0119 je z wynikiem odniesienia, wi\u0119c spasowanie z silnymi kartami kosztuje punkty. Po ostatnim rozdaniu wygrywa para z wi\u0119ksz\u0105 liczb\u0105 IMP-\u00F3w lub punkt\u00F3w; przy r\u00F3wnej sumie jest remis. Klawisz S odczytuje dotychczasowy wynik."),
            rule_section(:bots, "Licytacja z komputerowym partnerem",
              "Gracze komputerowi widz\u0105 tylko w\u0142asne karty, dziadka oraz zapowiedzi i karty, kt\u00F3re widz\u0105 wszyscy. Licytuj\u0105 prostym naturalnym systemem, dzi\u0119ki czemu \u0142atwiej zrozumie\u0107 ich zapowiedzi:",
              "- 1 bez atu oznacza od 15 do 17 punkt\u00F3w i r\u0119k\u0119 zr\u00F3wnowa\u017Con\u0105, a 2 bez atu \u2014 20 lub 21 punkt\u00F3w.",
              "- Otwarcie 1 kier albo 1 pik obiecuje co najmniej pi\u0119\u0107 kart w tym kolorze i zwykle 12 punkt\u00F3w lub wi\u0119cej. Bez pi\u0105tki w kolorze starszym bot otwiera 1 karo albo 1 trefl.",
              "- Otwarcie 2 kara, 2 kiery albo 2 piki jest s\u0142abe: to sze\u015Bciokartowy kolor i od 6 do 10 punkt\u00F3w.",
              "- Podniesienie twojego koloru oznacza fit. Podniesienie na wysoko\u015B\u0107 2 jest s\u0142abe, na 3 zaprasza do ko\u0144c\u00F3wki, a skok od razu do ko\u0144c\u00F3wki pokazuje siln\u0105 r\u0119k\u0119.",
              "Boty nigdy nie kontruj\u0105. Graj\u0105 te\u017C wed\u0142ug prostych zasad: drugi gracz w lewie dok\u0142ada nisko, chyba \u017Ce ma pewn\u0105 lew\u0119, dalsi gracze pr\u00F3buj\u0105 wzi\u0105\u0107 lew\u0119 jak najni\u017Csz\u0105 kart\u0105, a obro\u0144ca wychodzi w kolor partnera albo w sw\u00F3j d\u0142ugi kolor."),
            rule_section(:controls, "Skr\u00F3ty klawiszowe",
              "Enter na li\u015Bcie zapowiedzi: zg\u0142o\u015B wybran\u0105 zapowied\u017A.",
              "B: wybierz zapowied\u017A w swojej kolejce, a w innej chwili odczytaj licytacj\u0119.",
              "L: odczytaj licytacj\u0119.",
              "Ctrl+L: przegl\u0105daj licytacj\u0119.",
              "K: odczytaj kontrakt i lewy rozgrywaj\u0105cego.",
              "Enter na karcie: zagraj j\u0105.",
              "Tab: przejd\u017A mi\u0119dzy swoj\u0105 r\u0119k\u0105 a dziadkiem.",
              "Z: przejd\u017A do nast\u0119pnej karty, kt\u00F3r\u0105 mo\u017Cna zagra\u0107 z r\u0119ki b\u0119d\u0105cej na ruchu; je\u015Bli jest tylko jedna, zagraj j\u0105.",
              "Shift+Z: przejd\u017A do poprzedniej karty, kt\u00F3r\u0105 mo\u017Cna zagra\u0107.",
              "H: odczytaj swoj\u0105 r\u0119k\u0119.",
              "D: odczytaj r\u0119k\u0119 dziadka.",
              "C: odczytaj bie\u017C\u0105c\u0105 lew\u0119.",
              "Ctrl+C: przegl\u0105daj bie\u017C\u0105c\u0105 lew\u0119.",
              "F: odczytaj kolor wyj\u015Bcia.",
              "P: odczytaj poprzedni\u0105 lew\u0119.",
              "V: odczytaj rozdanie, za\u0142o\u017Cenia, kontrakt i lewy.",
              "I: odczytaj swoje miejsce, partnera i rol\u0119 w tym rozdaniu.",
              "S: odczytaj wynik.",
              "T: odczytaj, czyja jest tura.",
              "Shift+C: posortuj karty wed\u0142ug koloru.",
              "Shift+H: posortuj karty wed\u0142ug warto\u015Bci.",
              "Shift+M: przywr\u00F3\u0107 pierwotn\u0105 kolejno\u015B\u0107 kart.")
          ]
        when "ru"
          [
            rule_section(:aim, "\u0421\u0443\u0442\u044C \u0438\u0433\u0440\u044B",
              "\u0411\u0440\u0438\u0434\u0436 \u2014 \u043A\u0430\u0440\u0442\u043E\u0447\u043D\u0430\u044F \u0438\u0433\u0440\u0430 \u0434\u043B\u044F \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0447\u0435\u043B\u043E\u0432\u0435\u043A, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0438\u0433\u0440\u0430\u044E\u0442 \u0434\u0432\u0443\u043C\u044F \u043F\u0430\u0440\u0430\u043C\u0438. \u0412\u044B \u0438 \u0432\u0430\u0448 \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0432\u043C\u0435\u0441\u0442\u0435 \u043F\u0440\u043E\u0442\u0438\u0432 \u0434\u0440\u0443\u0433\u043E\u0439 \u043F\u0430\u0440\u044B. \u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0434\u0430\u0447\u0430 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0434\u0432\u0443\u0445 \u0447\u0430\u0441\u0442\u0435\u0439: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0438, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043F\u0430\u0440\u044B \u0441\u043E\u0440\u0435\u0432\u043D\u0443\u044E\u0442\u0441\u044F \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0430 \u0437\u0430\u0442\u0435\u043C \u0440\u043E\u0437\u044B\u0433\u0440\u044B\u0448\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u043C \u043F\u0430\u0440\u0430, \u043F\u043E\u043B\u0443\u0447\u0438\u0432\u0448\u0430\u044F \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0441\u0442\u0430\u0440\u0430\u0435\u0442\u0441\u044F \u0432\u0437\u044F\u0442\u044C \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u0432\u0437\u044F\u0442\u043E\u043A, \u0447\u0435\u043C \u043E\u0431\u0435\u0449\u0430\u043B\u0430.",
              "\u041E\u0447\u043A\u0438 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u044E\u0442\u0441\u044F \u0437\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u044B \u0438 \u0437\u0430 \u043F\u043E\u0434\u0441\u0430\u0434 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0430\u0440\u0430, \u0443 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u043A \u043A\u043E\u043D\u0446\u0443 \u043C\u0430\u0442\u0447\u0430 \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0447\u043A\u043E\u0432."),
            rule_section(:deal, "\u041F\u0430\u0440\u044B \u0438 \u0441\u0434\u0430\u0447\u0430",
              "\u041C\u0435\u0441\u0442\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E \u0441\u0442\u043E\u0440\u043E\u043D\u0430\u043C \u0441\u0432\u0435\u0442\u0430. \u0421\u0435\u0432\u0435\u0440 \u0438\u0433\u0440\u0430\u0435\u0442 \u0432 \u043F\u0430\u0440\u0435 \u0441 \u042E\u0433\u043E\u043C, \u0430 \u0412\u043E\u0441\u0442\u043E\u043A \u2014 \u0441 \u0417\u0430\u043F\u0430\u0434\u043E\u043C; \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u044B \u0441\u0438\u0434\u044F\u0442 \u0434\u0440\u0443\u0433 \u043D\u0430\u043F\u0440\u043E\u0442\u0438\u0432 \u0434\u0440\u0443\u0433\u0430. \u0415\u0441\u043B\u0438 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u0432\u044B\u0431\u0440\u0430\u043D\u044B \u043A\u043E\u043C\u0430\u043D\u0434\u044B, \u0434\u0432\u0430 \u0438\u0433\u0440\u043E\u043A\u0430 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0441\u0442\u0430\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430\u043C\u0438. \u0425\u043E\u0434 \u0432\u0441\u0435\u0433\u0434\u0430 \u043F\u0435\u0440\u0435\u0434\u0430\u0451\u0442\u0441\u044F \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435: \u0421\u0435\u0432\u0435\u0440, \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434.",
              "\u0421\u0434\u0430\u044E\u0442\u0441\u044F \u0432\u0441\u0435 52 \u043A\u0430\u0440\u0442\u044B, \u0442\u0430\u043A \u0447\u0442\u043E \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 13. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 H, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0440\u0443\u043A\u0443 \u043C\u0430\u0441\u0442\u044C \u0437\u0430 \u043C\u0430\u0441\u0442\u044C\u044E \u043E\u0442 \u0441\u0442\u0430\u0440\u0448\u0435\u0439 \u043A\u0430\u0440\u0442\u044B, \u0430 \u0432 \u043A\u043E\u043D\u0446\u0435 \u2014 \u0447\u0438\u0441\u043B\u043E \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B: \u0442\u0443\u0437 \u0441\u0442\u043E\u0438\u0442 4 \u043E\u0447\u043A\u0430, \u043A\u043E\u0440\u043E\u043B\u044C 3, \u0434\u0430\u043C\u0430 2, \u0432\u0430\u043B\u0435\u0442 1. \u042D\u0442\u0438 \u043E\u0447\u043A\u0438 \u043D\u0435 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0432 \u0441\u0447\u0451\u0442, \u043D\u043E \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442 \u043E\u0446\u0435\u043D\u0438\u0442\u044C \u0441\u0438\u043B\u0443 \u0440\u0443\u043A\u0438 \u0432 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0435. \u0412\u043E \u0432\u0441\u0435\u0439 \u043A\u043E\u043B\u043E\u0434\u0435 \u0438\u0445 40, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0441\u0440\u0435\u0434\u043D\u044F\u044F \u0440\u0443\u043A\u0430 \u2014 10 \u043E\u0447\u043A\u043E\u0432, \u0430 12 \u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u043E\u0431\u044B\u0447\u043D\u043E \u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E.",
              "\u0412 \u043A\u0430\u0436\u0434\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u2014 \u0442\u0443\u0437, \u0437\u0430\u0442\u0435\u043C \u043A\u043E\u0440\u043E\u043B\u044C, \u0434\u0430\u043C\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0441\u044F\u0442\u043A\u0430 \u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0434\u043E \u0434\u0432\u043E\u0439\u043A\u0438."),
            rule_section(:auction, "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F",
              "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044E \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441\u0434\u0430\u044E\u0449\u0438\u0439, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0433\u043E\u0432\u043E\u0440\u044F\u0442 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435. \u041A\u043E\u0433\u0434\u0430 \u043D\u0430\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u0432\u0430\u0448\u0430 \u043E\u0447\u0435\u0440\u0435\u0434\u044C, \u0432 \u0438\u0433\u0440\u043E\u0432\u043E\u043C \u043F\u043E\u043B\u0435 \u043F\u043E\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043F\u0438\u0441\u043E\u043A \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0445 \u0437\u0430\u044F\u0432\u043E\u043A. \u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0437\u0430\u044F\u0432\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u0422\u043E\u0442 \u0436\u0435 \u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u043A\u043B\u0430\u0432\u0438\u0448\u0430 B.",
              "\u0417\u0430\u044F\u0432\u043A\u0430 \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u0432\u0437\u044F\u0442\u043E\u043A \u0438 \u043A\u043E\u0437\u044B\u0440\u043D\u0443\u044E \u043C\u0430\u0441\u0442\u044C \u0438\u043B\u0438 \u0438\u0433\u0440\u0443 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F. \u041A \u043D\u0430\u0437\u0432\u0430\u043D\u043D\u043E\u043C\u0443 \u0447\u0438\u0441\u043B\u0443 \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0448\u0435\u0441\u0442\u044C: 1 \u0447\u0435\u0440\u0432\u0430 \u043E\u0431\u0435\u0449\u0430\u0435\u0442 7 \u0438\u0437 13 \u0432\u0437\u044F\u0442\u043E\u043A \u0441 \u043A\u043E\u0437\u044B\u0440\u0435\u043C \u0432 \u0447\u0435\u0440\u0432\u0430\u0445, \u0430 4 \u043F\u0438\u043A\u0438 \u2014 10 \u0432\u0437\u044F\u0442\u043E\u043A \u0441 \u043A\u043E\u0437\u044B\u0440\u0435\u043C \u0432 \u043F\u0438\u043A\u0430\u0445. \u041A\u0430\u0436\u0434\u0430\u044F \u0437\u0430\u044F\u0432\u043A\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0431\u044B\u0442\u044C \u0432\u044B\u0448\u0435 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0439. \u0411\u043E\u043B\u044C\u0448\u0435\u0435 \u0447\u0438\u0441\u043B\u043E \u0432\u0441\u0435\u0433\u0434\u0430 \u043F\u0435\u0440\u0435\u0431\u0438\u0432\u0430\u0435\u0442 \u043C\u0435\u043D\u044C\u0448\u0435\u0435, \u0430 \u043F\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043C\u0430\u0441\u0442\u0438 \u0438\u0434\u0443\u0442 \u043E\u0442 \u043C\u043B\u0430\u0434\u0448\u0435\u0439: \u0442\u0440\u0435\u0444\u044B, \u0431\u0443\u0431\u043D\u044B, \u0447\u0435\u0440\u0432\u044B, \u043F\u0438\u043A\u0438 \u0438 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F. \u041F\u043E\u0441\u043B\u0435 1 \u043F\u0438\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u044F\u0432\u0438\u0442\u044C 1 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u0438\u043B\u0438 \u043B\u044E\u0431\u0443\u044E \u0437\u0430\u044F\u0432\u043A\u0443 \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 2, \u043D\u043E \u043D\u0435 1 \u0447\u0435\u0440\u0432\u0430.",
              "\u0412\u043C\u0435\u0441\u0442\u043E \u0437\u0430\u044F\u0432\u043A\u0438 \u043C\u043E\u0436\u043D\u043E \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u043E\u0434\u0438\u043D \u0438\u0437 \u0442\u0430\u043A\u0438\u0445 \u0445\u043E\u0434\u043E\u0432:",
              "- \u041F\u0430\u0441: \u0432\u044B \u043D\u0435 \u0445\u043E\u0442\u0438\u0442\u0435 \u0441\u0435\u0439\u0447\u0430\u0441 \u0442\u043E\u0440\u0433\u043E\u0432\u0430\u0442\u044C\u0441\u044F. \u041F\u0430\u0441 \u043D\u0435 \u043C\u0435\u0448\u0430\u0435\u0442 \u0432\u0430\u043C \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0437\u0430\u044F\u0432\u043A\u0443 \u043F\u043E\u0437\u0436\u0435 \u0432 \u0442\u043E\u0439 \u0436\u0435 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u0435.",
              "- \u041A\u043E\u043D\u0442\u0440\u0430: \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u0430 \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430, \u0434\u0430\u0436\u0435 \u0435\u0441\u043B\u0438 \u0437\u0430 \u043D\u0435\u0439 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u043B\u0438 \u043F\u0430\u0441\u044B. \u0415\u0441\u043B\u0438 \u044D\u0442\u0430 \u0437\u0430\u044F\u0432\u043A\u0430 \u0441\u0442\u0430\u043D\u0435\u0442 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C, \u043E\u0431\u0435 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u0431\u043E\u043B\u044C\u0448\u0435: \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u2014 \u0437\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435, \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0438 \u2014 \u0437\u0430 \u043F\u043E\u0434\u0441\u0430\u0434.",
              "- \u0420\u0435\u043A\u043E\u043D\u0442\u0440\u0430: \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u0430 \u0442\u043E\u043B\u044C\u043A\u043E \u0442\u043E\u0433\u0434\u0430, \u043A\u043E\u0433\u0434\u0430 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u0437\u0430\u043A\u043E\u043D\u0442\u0440\u0438\u043B \u0437\u0430\u044F\u0432\u043A\u0443 \u0432\u0430\u0448\u0435\u0439 \u043F\u0430\u0440\u044B. \u041E\u043D\u0430 \u0435\u0449\u0451 \u0440\u0430\u0437 \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442 \u0441\u0442\u0430\u0432\u043A\u0438.",
              "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0442\u0440\u043E\u0435 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u043F\u043E\u0434\u0440\u044F\u0434 \u043F\u0430\u0441\u0443\u044E\u0442. \u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0437\u0430\u044F\u0432\u043A\u0430 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C. \u0415\u0441\u043B\u0438 \u0432 \u0441\u0430\u043C\u043E\u043C \u043D\u0430\u0447\u0430\u043B\u0435 \u043F\u0430\u0441\u0443\u044E\u0442 \u0432\u0441\u0435 \u0447\u0435\u0442\u0432\u0435\u0440\u043E, \u043D\u0438\u043A\u0442\u043E \u043D\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432, \u0430 \u043A\u0430\u0440\u0442\u044B \u0437\u0430\u043D\u043E\u0432\u043E \u0441\u0434\u0430\u0451\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 L \u0437\u0430\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E, \u0430 Ctrl+L \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0435\u0451 \u0437\u0430\u044F\u0432\u043A\u0443 \u0437\u0430 \u0437\u0430\u044F\u0432\u043A\u043E\u0439."),
            rule_section(:contract, "\u041A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0438 \u0431\u043E\u043B\u0432\u0430\u043D",
              "\u041F\u0430\u0440\u0430, \u0441\u0434\u0435\u043B\u0430\u0432\u0448\u0430\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0437\u0430\u044F\u0432\u043A\u0443, \u0434\u043E\u043B\u0436\u043D\u0430 \u0432\u0437\u044F\u0442\u044C \u043E\u0431\u0435\u0449\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0432\u0437\u044F\u0442\u043E\u043A, \u0430 \u0434\u0440\u0443\u0433\u0430\u044F \u043F\u0430\u0440\u0430 \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442\u0441\u044F. \u0420\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u043C \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0442\u043E\u0442 \u0438\u0433\u0440\u043E\u043A \u044D\u0442\u043E\u0439 \u043F\u0430\u0440\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u043F\u0435\u0440\u0432\u044B\u043C \u043D\u0430\u0437\u0432\u0430\u043B \u043C\u0430\u0441\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0438\u043B\u0438 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F. \u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, \u0435\u0441\u043B\u0438 \u0421\u0435\u0432\u0435\u0440 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E \u0437\u0430\u044F\u0432\u043A\u043E\u0439 1 \u0447\u0435\u0440\u0432\u0430, \u042E\u0433 \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442 \u0434\u043E 4 \u0447\u0435\u0440\u0432 \u0438 \u0432\u0441\u0435 \u043F\u0430\u0441\u0443\u044E\u0442, \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0421\u0435\u0432\u0435\u0440, \u0445\u043E\u0442\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0437\u0430\u044F\u0432\u043A\u0443 \u0441\u0434\u0435\u043B\u0430\u043B \u042E\u0433.",
              "\u041F\u0435\u0440\u0432\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0430\u0442\u0430\u043A\u0443, \u043A\u043B\u0430\u0434\u0451\u0442 \u0438\u0433\u0440\u043E\u043A \u0441\u043B\u0435\u0432\u0430 \u043E\u0442 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043F\u0430\u0440\u0442\u043D\u0451\u0440 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u0431\u043E\u043B\u0432\u0430\u043D\u043E\u043C: \u0435\u0433\u043E \u043A\u0430\u0440\u0442\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044B \u0434\u043B\u044F \u0432\u0441\u0435\u0445, \u0438 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u0430\u0435\u0442 \u0438\u043C\u0438 \u0442\u0430\u043A \u0436\u0435, \u043A\u0430\u043A \u0441\u0432\u043E\u0438\u043C\u0438. \u0411\u043E\u043B\u0432\u0430\u043D \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u044D\u0442\u043E\u0439 \u0441\u0434\u0430\u0447\u0435.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 K \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0432\u0437\u044F\u0442\u043E\u043A \u043E\u043D \u0443\u0436\u0435 \u0432\u0437\u044F\u043B."),
            rule_section(:play, "\u0420\u043E\u0437\u044B\u0433\u0440\u044B\u0448",
              "\u041A\u0430\u0436\u0434\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0441\u043E\u0441\u0442\u043E\u0438\u0442 \u0438\u0437 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u0430\u0440\u0442, \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430 \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435. \u0427\u0442\u043E\u0431\u044B \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A \u043A\u0430\u0440\u0442\u0435 \u0432 \u0441\u0432\u043E\u0435\u0439 \u0440\u0443\u043A\u0435 \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Enter. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 Z \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442 \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043A\u0430\u0440\u0442\u0435, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u0430 Shift+Z \u2014 \u043A \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0439; \u0435\u0441\u043B\u0438 \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043C\u043E\u0436\u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u043D\u0443 \u043A\u0430\u0440\u0442\u0443, Z \u0441\u0440\u0430\u0437\u0443 \u0435\u0451 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u0435\u0442.",
              "\u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u0435\u0441\u0442\u044C \u043A\u0430\u0440\u0442\u044B \u043C\u0430\u0441\u0442\u0438 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430, \u043D\u0443\u0436\u043D\u043E \u0445\u043E\u0434\u0438\u0442\u044C \u0432 \u043C\u0430\u0441\u0442\u044C. \u0415\u0441\u043B\u0438 \u0442\u0430\u043A\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u043D\u0435\u0442, \u043C\u043E\u0436\u043D\u043E \u0441\u044B\u0433\u0440\u0430\u0442\u044C \u043B\u044E\u0431\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u043A\u043E\u0437\u044B\u0440\u044C, \u043D\u043E \u0431\u0438\u0442\u044C \u043A\u043E\u0437\u044B\u0440\u0435\u043C \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E. \u0412\u0437\u044F\u0442\u043A\u0443 \u0431\u0435\u0440\u0451\u0442 \u0441\u0442\u0430\u0440\u0448\u0438\u0439 \u043A\u043E\u0437\u044B\u0440\u044C, \u0430 \u0435\u0441\u043B\u0438 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 \u043D\u0435 \u0431\u044B\u043B\u043E \u2014 \u0441\u0442\u0430\u0440\u0448\u0430\u044F \u043A\u0430\u0440\u0442\u0430 \u043C\u0430\u0441\u0442\u0438 \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430. \u041A\u0430\u0440\u0442\u044B \u0434\u0440\u0443\u0433\u0438\u0445 \u043C\u0430\u0441\u0442\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0443 \u0432\u0437\u044F\u0442\u044C \u043D\u0435 \u043C\u043E\u0433\u0443\u0442. \u0412\u0437\u044F\u0432\u0448\u0438\u0439 \u0432\u0437\u044F\u0442\u043A\u0443 \u0434\u0435\u043B\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u0445\u043E\u0434 \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439.",
              "\u041A\u0430\u043A \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u044B \u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u0431\u043E\u043B\u0432\u0430\u043D\u0430. \u041A\u043E\u0433\u0434\u0430 \u043D\u0430\u0441\u0442\u0443\u043F\u0430\u0435\u0442 \u043E\u0447\u0435\u0440\u0435\u0434\u044C \u0431\u043E\u043B\u0432\u0430\u043D\u0430, \u043D\u0430\u0436\u043C\u0438\u0442\u0435 Tab, \u0447\u0442\u043E\u0431\u044B \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u043A \u0441\u043F\u0438\u0441\u043A\u0443 \u0435\u0433\u043E \u043A\u0430\u0440\u0442, \u0438\u043B\u0438 Z, \u0447\u0442\u043E\u0431\u044B \u0441\u0440\u0430\u0437\u0443 \u043E\u043A\u0430\u0437\u0430\u0442\u044C\u0441\u044F \u043D\u0430 \u043A\u0430\u0440\u0442\u0430\u0445, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0431\u043E\u043B\u0432\u0430\u043D \u043C\u043E\u0436\u0435\u0442 \u0441\u044B\u0433\u0440\u0430\u0442\u044C, \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u0430\u0440\u0442\u0443 \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 Enter. \u0420\u0443\u043A\u0443 \u0431\u043E\u043B\u0432\u0430\u043D\u0430 \u043B\u044E\u0431\u043E\u0439 \u0438\u0433\u0440\u043E\u043A \u043C\u043E\u0436\u0435\u0442 \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0435\u0439 D.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 C \u0437\u0430\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043A\u0430\u0440\u0442\u044B \u0442\u0435\u043A\u0443\u0449\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u0438, \u0430 F \u2014 \u043C\u0430\u0441\u0442\u044C \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430. P \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443 \u0438 \u0442\u043E\u0433\u043E, \u043A\u0442\u043E \u0435\u0451 \u0432\u0437\u044F\u043B.",
              "\u041A\u043E\u0433\u0434\u0430 \u0441\u044B\u0433\u0440\u0430\u043D\u044B \u0432\u0441\u0435 13 \u0432\u0437\u044F\u0442\u043E\u043A, \u0441\u0434\u0430\u0447\u0430 \u043F\u043E\u0434\u0441\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F, \u0430 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0441\u0434\u0430\u0451\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u043F\u043E \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0441\u0442\u0440\u0435\u043B\u043A\u0435."),
            rule_section(:scoring, "\u041E\u0447\u043A\u0438 \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442",
              "\u0421\u0447\u0438\u0442\u0430\u044E\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0437\u044F\u0442\u043A\u0438 \u0441\u0432\u0435\u0440\u0445 \u043F\u0435\u0440\u0432\u044B\u0445 \u0448\u0435\u0441\u0442\u0438. \u0415\u0441\u043B\u0438 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u043B \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u043A\u0430\u0436\u0434\u0430\u044F \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0441\u0442\u043E\u0438\u0442:",
              "- 20 \u043E\u0447\u043A\u043E\u0432 \u0432 \u0442\u0440\u0435\u0444\u0430\u0445 \u0438\u043B\u0438 \u0431\u0443\u0431\u043D\u0430\u0445;",
              "- 30 \u043E\u0447\u043A\u043E\u0432 \u0432 \u0447\u0435\u0440\u0432\u0430\u0445 \u0438\u043B\u0438 \u043F\u0438\u043A\u0430\u0445;",
              "- 40 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443 \u0432 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u0438 \u043F\u043E 30 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E.",
              "\u042D\u0442\u0438 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0440\u044B \u0438 \u0443\u0447\u0435\u0442\u0432\u0435\u0440\u044F\u044E\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u044B. \u041A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0441\u0442\u043E\u0438\u0442 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 100 \u0442\u0430\u043A\u0438\u0445 \u043E\u0447\u043A\u043E\u0432, \u2014 \u044D\u0442\u043E \u0433\u0435\u0439\u043C: \u0441\u0430\u043C\u044B\u0435 \u043D\u0438\u0437\u043A\u0438\u0435 \u0433\u0435\u0439\u043C\u044B \u2014 3 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F, 4 \u0447\u0435\u0440\u0432\u044B, 4 \u043F\u0438\u043A\u0438, 5 \u0442\u0440\u0435\u0444 \u0438 5 \u0431\u0443\u0431\u0435\u043D. \u041A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043F\u043E\u043C\u0435\u043D\u044C\u0448\u0435 \u2014 \u044D\u0442\u043E \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C.",
              "\u0418\u0433\u0440\u0430 \u0432 \u0437\u043E\u043D\u0435 \u043F\u043E\u0432\u044B\u0448\u0430\u0435\u0442 \u0438 \u043F\u0440\u0435\u043C\u0438\u0438, \u0438 \u0448\u0442\u0440\u0430\u0444\u044B. \u0412 \u043D\u0430\u0447\u0430\u043B\u0435 \u043A\u0430\u0436\u0434\u043E\u0439 \u0441\u0434\u0430\u0447\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F, \u043A\u0442\u043E \u0432 \u0437\u043E\u043D\u0435, \u0430 \u043A\u0442\u043E \u0434\u043E \u0437\u043E\u043D\u044B; \u043A\u043B\u0430\u0432\u0438\u0448\u0430 V \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u044D\u0442\u043E \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043D\u043E\u043C\u0435\u0440\u043E\u043C \u0441\u0434\u0430\u0447\u0438, \u0441\u0434\u0430\u044E\u0449\u0438\u043C, \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u043E\u043C \u0438 \u0432\u0437\u044F\u0442\u043A\u0430\u043C\u0438.",
              "\u0412\u0437\u044F\u0442\u043A\u0438 \u0441\u0432\u0435\u0440\u0445 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u043D\u0430\u0437\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043B\u0438\u0448\u043D\u0438\u043C\u0438. \u0411\u0435\u0437 \u043A\u043E\u043D\u0442\u0440\u044B \u043A\u0430\u0436\u0434\u0430\u044F \u0441\u0442\u043E\u0438\u0442 \u0441\u0442\u043E\u043B\u044C\u043A\u043E \u0436\u0435, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0430\u0437\u0430\u043D\u043D\u0430\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u0432 \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u041F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0442\u0440\u044B \u043A\u0430\u0436\u0434\u0430\u044F \u043B\u0438\u0448\u043D\u044F\u044F \u0432\u0437\u044F\u0442\u043A\u0430 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 100 \u043E\u0447\u043A\u043E\u0432, \u0430 \u0432 \u0437\u043E\u043D\u0435 200; \u043F\u043E\u0441\u043B\u0435 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u044B 200 \u0438\u043B\u0438 400. \u0417\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0437\u0430\u043A\u043E\u043D\u0442\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442\u0441\u044F 50 \u043E\u0447\u043A\u043E\u0432, \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u2014 100.",
              "\u041C\u0430\u043B\u044B\u0439 \u0448\u043B\u0435\u043C, \u0442\u043E \u0435\u0441\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 6, \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u0440\u0435\u043C\u0438\u044E 500, \u0430 \u0432 \u0437\u043E\u043D\u0435 750. \u0411\u043E\u043B\u044C\u0448\u043E\u0439 \u0448\u043B\u0435\u043C, \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u043D\u0430 \u0443\u0440\u043E\u0432\u043D\u0435 7, \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 1000, \u0430 \u0432 \u0437\u043E\u043D\u0435 1500.",
              "\u0415\u0441\u043B\u0438 \u0440\u0430\u0437\u044B\u0433\u0440\u044B\u0432\u0430\u044E\u0449\u0438\u0439 \u0432\u0437\u044F\u043B \u043C\u0435\u043D\u044C\u0448\u0435 \u0432\u0437\u044F\u0442\u043E\u043A, \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u044E\u0442 \u043E\u0447\u043A\u0438 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443:",
              "- \u0431\u0435\u0437 \u043A\u043E\u043D\u0442\u0440\u044B: \u043F\u043E 50 \u0437\u0430 \u0432\u0437\u044F\u0442\u043A\u0443, \u0430 \u0432 \u0437\u043E\u043D\u0435 \u043F\u043E 100;",
              "- \u0441 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u0434\u043E \u0437\u043E\u043D\u044B: 100 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443, \u043F\u043E 200 \u0437\u0430 \u0432\u0442\u043E\u0440\u0443\u044E \u0438 \u0442\u0440\u0435\u0442\u044C\u044E \u0438 \u043F\u043E 300 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E;",
              "- \u0441 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u0432 \u0437\u043E\u043D\u0435: 200 \u0437\u0430 \u043F\u0435\u0440\u0432\u0443\u044E \u0432\u0437\u044F\u0442\u043A\u0443 \u0438 \u043F\u043E 300 \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E;",
              "- \u0441 \u0440\u0435\u043A\u043E\u043D\u0442\u0440\u043E\u0439: \u0432\u0434\u0432\u043E\u0435 \u0431\u043E\u043B\u044C\u0448\u0435, \u0447\u0435\u043C \u0441 \u043A\u043E\u043D\u0442\u0440\u043E\u0439.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 2 \u043F\u0438\u043A\u0438 \u0441 \u043A\u043E\u043D\u0442\u0440\u043E\u0439 \u0434\u043E \u0437\u043E\u043D\u044B, \u0441\u044B\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0441 \u043B\u0438\u0448\u043D\u0435\u0439 \u0432\u0437\u044F\u0442\u043A\u043E\u0439, \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 120 \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442, 50 \u0437\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435 \u0437\u0430\u043A\u043E\u043D\u0442\u0440\u0435\u043D\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442\u0430 \u0438 100 \u0437\u0430 \u043B\u0438\u0448\u043D\u044E\u044E \u0432\u0437\u044F\u0442\u043A\u0443. \u0422\u043E\u0442 \u0436\u0435 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0431\u0435\u0437 \u0434\u0432\u0443\u0445 \u0434\u0430\u0451\u0442 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0430\u043C 300."),
            rule_section(:rubber, "\u0418\u0433\u0440\u0430 \u043D\u0430 \u0440\u043E\u0431\u0431\u0435\u0440",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u0438\u0433\u0440\u0430\u044E\u0442 \u0440\u043E\u0431\u0431\u0435\u0440. \u0420\u043E\u0431\u0431\u0435\u0440 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u043E\u0434\u043D\u0430 \u043F\u0430\u0440\u0430 \u0432\u044B\u0438\u0433\u0440\u0430\u0435\u0442 \u0434\u0432\u0430 \u0433\u0435\u0439\u043C\u0430, \u0430 \u043C\u0430\u0442\u0447 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043F\u0430\u0440\u0430 \u0441 \u0431\u043E\u043B\u044C\u0448\u0435\u0439 \u043E\u0431\u0449\u0435\u0439 \u0441\u0443\u043C\u043C\u043E\u0439 \u043E\u0447\u043A\u043E\u0432. \u041E\u0431\u044B\u0447\u043D\u043E \u044D\u0442\u043E \u043F\u0430\u0440\u0430, \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u0440\u043E\u0431\u0431\u0435\u0440, \u043D\u043E \u043D\u0435 \u0432\u0441\u0435\u0433\u0434\u0430; \u043F\u0440\u0438 \u0440\u0430\u0432\u043D\u044B\u0445 \u0441\u0443\u043C\u043C\u0430\u0445 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u043D\u0438\u0447\u044C\u044F.",
              "\u041E\u0447\u043A\u0438 \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u0430\u043A\u0442 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439, \u0430 \u0432\u0441\u0435 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u2014 \u043D\u0430\u0434 \u0447\u0435\u0440\u0442\u043E\u0439. \u041F\u0430\u0440\u0430 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0433\u0435\u0439\u043C, \u043A\u043E\u0433\u0434\u0430 \u0435\u0451 \u043E\u0447\u043A\u0438 \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439 \u0434\u043E\u0441\u0442\u0438\u0433\u0430\u044E\u0442 100, \u0437\u0430 \u043E\u0434\u043D\u0443 \u0441\u0434\u0430\u0447\u0443 \u0438\u043B\u0438 \u0438\u0437 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u0445 \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u044B\u0445 \u0437\u0430\u043F\u0438\u0441\u0435\u0439. \u041F\u043E\u0441\u043B\u0435 \u0433\u0435\u0439\u043C\u0430 \u043E\u0431\u0435 \u043F\u0430\u0440\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0441 \u043D\u0443\u043B\u044F \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439; \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u044B\u0435 \u0437\u0430\u043F\u0438\u0441\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043D\u0430\u0431\u0440\u0430\u043B\u0438 \u043A \u043F\u0440\u043E\u0448\u043B\u043E\u043C\u0443 \u0433\u0435\u0439\u043C\u0443, \u0438\u043C \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u043F\u043E\u043C\u043E\u0433\u0430\u044E\u0442.",
              "\u041F\u0430\u0440\u0430, \u0432\u044B\u0438\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u0433\u0435\u0439\u043C, \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432 \u0437\u043E\u043D\u0435 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u043E\u0431\u0431\u0435\u0440\u0430. \u0417\u0430 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0439 \u0440\u043E\u0431\u0431\u0435\u0440 \u043D\u0430\u0447\u0438\u0441\u043B\u044F\u0435\u0442\u0441\u044F 700 \u043E\u0447\u043A\u043E\u0432, \u0435\u0441\u043B\u0438 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043D\u0435 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043D\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0433\u0435\u0439\u043C\u0430, \u0438 500, \u0435\u0441\u043B\u0438 \u0432\u044B\u0438\u0433\u0440\u0430\u043B\u0438 \u043E\u0434\u0438\u043D.",
              "\u041D\u0430\u0434 \u0447\u0435\u0440\u0442\u043E\u0439 \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u043E\u043D\u0451\u0440\u044B, \u0443 \u043A\u043E\u0433\u043E \u0431\u044B \u043E\u043D\u0438 \u043D\u0438 \u0431\u044B\u043B\u0438, \u0434\u0430\u0436\u0435 \u0443 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A\u0430. \u0427\u0435\u0442\u044B\u0440\u0435 \u0438\u0437 \u043F\u044F\u0442\u0438 \u0441\u0442\u0430\u0440\u0448\u0438\u0445 \u043A\u043E\u0437\u044B\u0440\u0435\u0439 (\u0442\u0443\u0437, \u043A\u043E\u0440\u043E\u043B\u044C, \u0434\u0430\u043C\u0430, \u0432\u0430\u043B\u0435\u0442, \u0434\u0435\u0441\u044F\u0442\u043A\u0430) \u0432 \u043E\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0435 \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 100, \u0430 \u0432\u0441\u0435 \u043F\u044F\u0442\u044C \u2014 150. \u0412 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0442\u0443\u0437\u0430 \u0432 \u043E\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0435 \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 150. \u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u043D\u0451\u0440\u043E\u0432 \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430.",
              "\u041A\u043B\u0430\u0432\u0438\u0448\u0430 S \u0437\u0430\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u043E\u0447\u043A\u0438 \u043F\u043E\u0434 \u0447\u0435\u0440\u0442\u043E\u0439 \u0438 \u043D\u0430\u0434 \u0447\u0435\u0440\u0442\u043E\u0439, \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0433\u0435\u0439\u043C\u044B \u0438 \u0441\u0443\u043C\u043C\u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u043F\u0430\u0440\u044B, \u0430 \u0437\u0430\u0442\u0435\u043C \u0441\u0447\u0451\u0442 \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0433\u0435\u0439\u043C\u0430."),
            rule_section(:duplicate, "\u0421\u043F\u043E\u0440\u0442\u0438\u0432\u043D\u044B\u0439 \u0431\u0440\u0438\u0434\u0436",
              "\u0412 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0441\u0442\u043E\u043B\u0430 \u0432\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u043C\u043E\u0436\u043D\u043E \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u0441\u043F\u043E\u0440\u0442\u0438\u0432\u043D\u044B\u0439 \u0431\u0440\u0438\u0434\u0436. \u0422\u043E\u0433\u0434\u0430 \u043C\u0430\u0442\u0447 \u0434\u043B\u0438\u0442\u0441\u044F \u0437\u0430\u0434\u0430\u043D\u043D\u043E\u0435 \u0447\u0438\u0441\u043B\u043E \u0441\u0434\u0430\u0447: 4, 8, 12, 16 \u0438\u043B\u0438 24, \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E 8. \u041D\u043E\u043C\u0435\u0440 \u0441\u0434\u0430\u0447\u0438 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u0437\u043E\u043D\u044B \u043F\u043E \u0442\u043E\u043C\u0443 \u0436\u0435 \u0446\u0438\u043A\u043B\u0443, \u0447\u0442\u043E \u0438 \u0432 \u0431\u0440\u0438\u0434\u0436\u0435\u0432\u044B\u0445 \u043A\u043B\u0443\u0431\u0430\u0445. \u0421\u0434\u0430\u0447\u0443 1 \u0441\u0434\u0430\u0451\u0442 \u0421\u0435\u0432\u0435\u0440, \u0438 \u043E\u0431\u0435 \u043F\u0430\u0440\u044B \u0434\u043E \u0437\u043E\u043D\u044B; \u0441\u0434\u0430\u0447\u0443 2 \u2014 \u0412\u043E\u0441\u0442\u043E\u043A \u043F\u0440\u0438 \u0437\u043E\u043D\u0435 \u0421\u0435\u0432\u0435\u0440\u0430 \u0438 \u042E\u0433\u0430; \u0441\u0434\u0430\u0447\u0443 3 \u2014 \u042E\u0433 \u043F\u0440\u0438 \u0437\u043E\u043D\u0435 \u0412\u043E\u0441\u0442\u043E\u043A\u0430 \u0438 \u0417\u0430\u043F\u0430\u0434\u0430; \u0441\u0434\u0430\u0447\u0443 4 \u2014 \u0417\u0430\u043F\u0430\u0434, \u043A\u043E\u0433\u0434\u0430 \u0432 \u0437\u043E\u043D\u0435 \u043E\u0431\u0435 \u043F\u0430\u0440\u044B.",
              "\u041A\u0430\u0436\u0434\u0430\u044F \u0441\u0434\u0430\u0447\u0430 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u0413\u0435\u0439\u043C \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u043F\u0440\u0435\u043C\u0438\u044E 300, \u0430 \u0432 \u0437\u043E\u043D\u0435 500, \u0447\u0430\u0441\u0442\u0438\u0447\u043D\u0430\u044F \u0437\u0430\u043F\u0438\u0441\u044C \u2014 50. \u0412\u0441\u0451 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u043E\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u0442\u0430\u043A, \u043A\u0430\u043A \u043E\u043F\u0438\u0441\u0430\u043D\u043E \u0432\u044B\u0448\u0435. \u041E\u043D\u0451\u0440\u043E\u0432 \u0438 \u0440\u043E\u0431\u0431\u0435\u0440\u0430 \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442.",
              "\u0412 \u043A\u043B\u0443\u0431\u0435 \u043E\u0434\u043D\u0438 \u0438 \u0442\u0435 \u0436\u0435 \u0441\u0434\u0430\u0447\u0438 \u0438\u0433\u0440\u0430\u044E\u0442\u0441\u044F \u0437\u0430 \u043C\u043D\u043E\u0433\u0438\u043C\u0438 \u0441\u0442\u043E\u043B\u0430\u043C\u0438, \u0438 \u043F\u0430\u0440\u044B \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u044E\u0442 \u0441\u0432\u043E\u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u044B. \u0417\u0434\u0435\u0441\u044C \u0441\u0442\u043E\u043B \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0434\u0438\u043D, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0432\u0430\u0448 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441 \u044D\u0442\u0430\u043B\u043E\u043D\u043D\u044B\u043C: \u043E\u0446\u0435\u043D\u043A\u043E\u0439 \u0442\u043E\u0433\u043E, \u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043E\u0431\u044B\u0447\u043D\u043E \u043F\u0440\u0438\u043D\u043E\u0441\u044F\u0442 \u0442\u0430\u043A\u0438\u0435 \u043A\u0430\u0440\u0442\u044B, \u043F\u043E \u0441\u0443\u043C\u043C\u0435 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0444\u0438\u0433\u0443\u0440\u044B \u0443 \u0431\u043E\u043B\u0435\u0435 \u0441\u0438\u043B\u044C\u043D\u043E\u0439 \u043F\u0430\u0440\u044B. \u0415\u0441\u043B\u0438 \u0443 \u043A\u0430\u0436\u0434\u043E\u0439 \u043F\u0430\u0440\u044B \u043F\u043E 20 \u043E\u0447\u043A\u043E\u0432, \u044D\u0442\u0430\u043B\u043E\u043D \u0440\u0430\u0432\u0435\u043D \u043D\u0443\u043B\u044E. \u041F\u0440\u0438 23 \u043E\u0447\u043A\u0430\u0445 \u0431\u043E\u043B\u0435\u0435 \u0441\u0438\u043B\u044C\u043D\u0430\u044F \u043F\u0430\u0440\u0430 \u0434\u043E\u043B\u0436\u043D\u0430 \u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C 110, \u043F\u0440\u0438 26 \u043E\u0447\u043A\u0430\u0445 \u2014 400, \u0430 \u0432 \u0437\u043E\u043D\u0435 600, \u043F\u0440\u0438 33 \u043E\u0447\u043A\u0430\u0445 \u2014 \u043C\u0430\u043B\u044B\u0439 \u0448\u043B\u0435\u043C \u0437\u0430 980, \u0430 \u0432 \u0437\u043E\u043D\u0435 1430. \u041E\u0446\u0435\u043D\u043A\u0430 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0440\u0430\u0441\u043A\u043B\u0430\u0434, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0445\u043E\u0440\u043E\u0448\u0438\u0439 \u0444\u0438\u0442 \u0438\u043B\u0438 \u043D\u0435\u043E\u0431\u044B\u0447\u043D\u043E\u0435 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043C\u043E\u0436\u0435\u0442 \u0441\u0442\u043E\u0438\u0442\u044C \u0433\u043E\u0440\u0430\u0437\u0434\u043E \u0431\u043E\u043B\u044C\u0448\u0435.",
              "\u0421\u043F\u043E\u0441\u043E\u0431 \u0441\u0440\u0430\u0432\u043D\u0435\u043D\u0438\u044F \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0430:",
              "- IMP (\u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E): \u0440\u0430\u0437\u043D\u0438\u0446\u0430 \u0441 \u044D\u0442\u0430\u043B\u043E\u043D\u043E\u043C \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442\u0441\u044F \u0432 \u043C\u0435\u0436\u0434\u0443\u043D\u0430\u0440\u043E\u0434\u043D\u044B\u0435 \u043C\u0430\u0442\u0447\u0435\u0432\u044B\u0435 \u043E\u0447\u043A\u0438. \u0420\u0430\u0437\u043D\u0438\u0446\u0430 \u0434\u043E 10 \u043E\u0447\u043A\u043E\u0432 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0434\u0430\u0451\u0442, \u043E\u0442 20 \u0434\u043E 40 \u2014 \u044D\u0442\u043E 1 IMP, \u043E\u0442 50 \u0434\u043E 80 \u2014 2, \u043E\u0442 90 \u0434\u043E 120 \u2014 3. \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u0440\u0430\u0437\u043D\u0438\u0446\u044B \u0434\u0430\u044E\u0442 \u0431\u043E\u043B\u044C\u0448\u0435, \u043D\u043E \u0432\u0441\u0451 \u043C\u0435\u0434\u043B\u0435\u043D\u043D\u0435\u0435: 420 \u2014 \u044D\u0442\u043E 9 IMP, \u0430 4000 \u0438 \u0431\u043E\u043B\u044C\u0448\u0435 \u2014 \u043C\u0430\u043A\u0441\u0438\u043C\u0430\u043B\u044C\u043D\u044B\u0435 24. IMP \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u0430\u0440\u0430, \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u043B\u0443\u0447\u0448\u0435 \u044D\u0442\u0430\u043B\u043E\u043D\u0430.",
              "- \u041C\u0430\u0442\u0447\u043F\u043E\u0439\u043D\u0442\u044B: \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0441\u0434\u0430\u0447\u0435 \u043F\u0430\u0440\u0430, \u0441\u044B\u0433\u0440\u0430\u0432\u0448\u0430\u044F \u043B\u0443\u0447\u0448\u0435 \u044D\u0442\u0430\u043B\u043E\u043D\u0430, \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 2 \u043E\u0447\u043A\u0430, \u0430 \u0434\u0440\u0443\u0433\u0430\u044F 0; \u043F\u0440\u0438 \u0440\u0430\u0432\u043D\u043E\u043C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442\u0435 \u043A\u0430\u0436\u0434\u0430\u044F \u043F\u0430\u0440\u0430 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 1. \u0418\u0442\u043E\u0433\u043E\u0432\u044B\u0439 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u043F\u0440\u043E\u0446\u0435\u043D\u0442 \u043E\u0442 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432.",
              "\u0421\u0434\u0430\u0447\u0430, \u0432 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0432\u0441\u0435 \u0447\u0435\u0442\u0432\u0435\u0440\u043E \u0441\u043F\u0430\u0441\u043E\u0432\u0430\u043B\u0438, \u0442\u043E\u0436\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F: \u0435\u0451 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0440\u0430\u0432\u0435\u043D \u043D\u0443\u043B\u044E \u0438 \u0441\u0440\u0430\u0432\u043D\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0441 \u044D\u0442\u0430\u043B\u043E\u043D\u043E\u043C, \u0442\u0430\u043A \u0447\u0442\u043E \u043F\u0430\u0441 \u0441 \u0441\u0438\u043B\u044C\u043D\u044B\u043C\u0438 \u043A\u0430\u0440\u0442\u0430\u043C\u0438 \u0441\u0442\u043E\u0438\u0442 \u043E\u0447\u043A\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u0441\u0434\u0430\u0447\u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0430\u0440\u0430 \u0441 \u0431\u043E\u043B\u044C\u0448\u0438\u043C \u0447\u0438\u0441\u043B\u043E\u043C IMP \u0438\u043B\u0438 \u043E\u0447\u043A\u043E\u0432; \u043F\u0440\u0438 \u0440\u0430\u0432\u043D\u043E\u0439 \u0441\u0443\u043C\u043C\u0435 \u2014 \u043D\u0438\u0447\u044C\u044F. \u041A\u043B\u0430\u0432\u0438\u0448\u0430 S \u0437\u0430\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0441\u0447\u0451\u0442."),
            rule_section(:bots, "\u0422\u043E\u0440\u0433\u043E\u0432\u043B\u044F \u0441 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u043D\u044B\u043C \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u043E\u043C",
              "\u041A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u043D\u044B\u0435 \u0438\u0433\u0440\u043E\u043A\u0438 \u0432\u0438\u0434\u044F\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u0432\u043E\u0438 \u043A\u0430\u0440\u0442\u044B, \u0431\u043E\u043B\u0432\u0430\u043D\u0430 \u0438 \u0442\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u0438 \u043A\u0430\u0440\u0442\u044B, \u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0432\u0438\u0434\u044F\u0442 \u0432\u0441\u0435. \u041E\u043D\u0438 \u0442\u043E\u0440\u0433\u0443\u044E\u0442\u0441\u044F \u043F\u043E \u043F\u0440\u043E\u0441\u0442\u043E\u0439 \u0435\u0441\u0442\u0435\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0439 \u0441\u0438\u0441\u0442\u0435\u043C\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0445 \u0437\u0430\u044F\u0432\u043A\u0438 \u043B\u0435\u0433\u043A\u043E \u043F\u043E\u043D\u044F\u0442\u044C:",
              "- 1 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043E\u0442 15 \u0434\u043E 17 \u043E\u0447\u043A\u043E\u0432 \u0438 \u0440\u0430\u0432\u043D\u043E\u043C\u0435\u0440\u043D\u0443\u044E \u0440\u0443\u043A\u0443, 2 \u0431\u0435\u0437 \u043A\u043E\u0437\u044B\u0440\u044F \u2014 20 \u0438\u043B\u0438 21.",
              "- \u041E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 1 \u0447\u0435\u0440\u0432\u0430 \u0438\u043B\u0438 1 \u043F\u0438\u043A\u0430 \u043E\u0431\u0435\u0449\u0430\u0435\u0442 \u043D\u0435 \u043C\u0435\u043D\u044C\u0448\u0435 \u043F\u044F\u0442\u0438 \u043A\u0430\u0440\u0442 \u0432 \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0438 \u043E\u0431\u044B\u0447\u043D\u043E 12 \u043E\u0447\u043A\u043E\u0432 \u0438\u043B\u0438 \u0431\u043E\u043B\u044C\u0448\u0435. \u0411\u0435\u0437 \u043F\u044F\u0442\u0438\u043A\u0430\u0440\u0442\u043E\u0447\u043D\u043E\u0439 \u0441\u0442\u0430\u0440\u0448\u0435\u0439 \u043C\u0430\u0441\u0442\u0438 \u0431\u043E\u0442 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0442\u043E\u0440\u0433\u043E\u0432\u043B\u044E \u0437\u0430\u044F\u0432\u043A\u043E\u0439 1 \u0431\u0443\u0431\u043D\u0430 \u0438\u043B\u0438 1 \u0442\u0440\u0435\u0444\u0430.",
              "- \u041E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 2 \u0431\u0443\u0431\u043D\u044B, 2 \u0447\u0435\u0440\u0432\u044B \u0438\u043B\u0438 2 \u043F\u0438\u043A\u0438 \u0441\u043B\u0430\u0431\u043E\u0435: \u0448\u0435\u0441\u0442\u0438\u043A\u0430\u0440\u0442\u043E\u0447\u043D\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u0438 \u043E\u0442 6 \u0434\u043E 10 \u043E\u0447\u043A\u043E\u0432.",
              "- \u041F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0432\u0430\u0448\u0435\u0439 \u043C\u0430\u0441\u0442\u0438 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0444\u0438\u0442. \u041F\u043E\u0432\u044B\u0448\u0435\u043D\u0438\u0435 \u0434\u043E \u0443\u0440\u043E\u0432\u043D\u044F 2 \u0441\u043B\u0430\u0431\u043E\u0435, \u0434\u043E 3 \u043F\u0440\u0438\u0433\u043B\u0430\u0448\u0430\u0435\u0442 \u0432 \u0433\u0435\u0439\u043C, \u0430 \u043F\u0440\u044B\u0436\u043E\u043A \u0441\u0440\u0430\u0437\u0443 \u0432 \u0433\u0435\u0439\u043C \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u0438\u043B\u044C\u043D\u0443\u044E \u0440\u0443\u043A\u0443.",
              "\u0411\u043E\u0442\u044B \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u043A\u043E\u043D\u0442\u0440\u044F\u0442. \u0418\u0433\u0440\u0430\u044E\u0442 \u043E\u043D\u0438 \u0442\u043E\u0436\u0435 \u043F\u043E \u043F\u0440\u043E\u0441\u0442\u044B\u043C \u043F\u0440\u0430\u0432\u0438\u043B\u0430\u043C: \u0432\u0442\u043E\u0440\u043E\u0439 \u0438\u0433\u0440\u043E\u043A \u0432\u043E \u0432\u0437\u044F\u0442\u043A\u0435 \u043A\u043B\u0430\u0434\u0451\u0442 \u043C\u043B\u0430\u0434\u0448\u0443\u044E \u043A\u0430\u0440\u0442\u0443, \u0435\u0441\u043B\u0438 \u0443 \u043D\u0435\u0433\u043E \u043D\u0435\u0442 \u0432\u0435\u0440\u043D\u043E\u0439 \u0432\u0437\u044F\u0442\u043A\u0438, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0441\u0442\u0430\u0440\u0430\u044E\u0442\u0441\u044F \u0432\u0437\u044F\u0442\u044C \u0432\u0437\u044F\u0442\u043A\u0443 \u043A\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u0431\u043E\u043B\u0435\u0435 \u043C\u043B\u0430\u0434\u0448\u0435\u0439 \u043A\u0430\u0440\u0442\u043E\u0439, \u0430 \u0437\u0430\u0449\u0438\u0442\u043D\u0438\u043A \u0445\u043E\u0434\u0438\u0442 \u0432 \u043C\u0430\u0441\u0442\u044C \u043F\u0430\u0440\u0442\u043D\u0451\u0440\u0430 \u0438\u043B\u0438 \u0432 \u0441\u0432\u043E\u044E \u0434\u043B\u0438\u043D\u043D\u0443\u044E \u043C\u0430\u0441\u0442\u044C."),
            rule_section(:controls, "\u0421\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u044F \u043A\u043B\u0430\u0432\u0438\u0448",
